window.QUESTION_BANK = [{"id":1,"question":"藻類的能量來源及最基本之生理特性是?","options":["光合作用","分裂生殖","好氧性","厭氧性"],"answer":1,"category":"微生物與生物處理基礎"},{"id":2,"question":"相於傳統式活性污泥法，下列有關延長曝氣法的敘述何者有誤?","options":["提供足夠之水力停留時間","提供足夠之污泥齡","食微比較低","形成的膠羽較不易凝聚"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":3,"question":"一般而言，水力停留時間較短的厭氧生物處理系統是?","options":["家庭化糞池","接觸曝氣法","滴濾池法","厭氧流體化床反應器"],"answer":1,"category":"厭氧生物處理"},{"id":4,"question":"下列何者不是厭氧生物處理系統之優點?","options":["反應槽之污泥濃度可以不高","產生的污泥量少，相對地無機營養物質需要量就較少","長時間未供應有機物，反應槽內生物仍不會去活性","產物甲烷可當能源"],"answer":1,"category":"厭氧生物處理"},{"id":5,"question":"下列種操作是批次活性污泥法所特有的?","options":["考量濾材之填充率與處理時間之關係","考量池深與曝氣器選用之關係","考量進流時間之比值","考量反沖洗與處理效率之關係"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":6,"question":"下列何種操作是接觸曝氣法所獨有的?","options":["進流、反應、沉降與出流程序分開","間歇曝氣","反沖法","利用豎軸之慢速曝氣器"],"answer":3,"category":"附著生長與生物膜"},{"id":7,"question":"化學自營性生物之性質為","options":["利用二氧化碳作為碳源","自氧化無機化合物獲得能量","利用有機化合物獲得食物","能從光獲得能源"],"answer":2,"category":"微生物與生物處理基礎"},{"id":8,"question":"生物反應槽內填充適當大小介值，以作為污泥(微生物)附著之擔體","options":["氧化渠法","上流式厭氧污泥床法","厭氧流體化床及應器","批式活性污泥法"],"answer":3,"category":"附著生長與生物膜"},{"id":9,"question":"生物處理有機物氧化之最終氫接受者，包括?","options":["自由氧","硫酸鹽","硝酸鹽","以上皆是"],"answer":4,"category":"微生物與生物處理基礎"},{"id":10,"question":"生物處理系統中，當可利用有機物缺乏時，微生物代謝將發生何種變化?","options":["進入對數增殖期","進入減率增殖期","進入體內呼吸期","進入死亡期"],"answer":3,"category":"微生物與生物處理基礎"},{"id":11,"question":"生物處理系統設有迴流污泥設施之目的是?","options":["增加反應槽內之菌體濃度","調節進流有機物負荷","維持反應槽內流速","回收水資源"],"answer":1,"category":"活性污泥與操作控制"},{"id":12,"question":"為維持氧化渠內物質的混合懸浮移動，需控制渠道水流速約為多少?","options":["45cm/sec","45cm/min","45mm/sec","45ammin"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":13,"question":"SV30 20mg/L，如水樣之MLSS2，000mg/L時，請估算水樣之SVI值?","options":["10","100","1，000","1"],"answer":1,"category":"活性污泥與操作控制"},{"id":14,"question":"下列有關好氧(與)厭氧處理程序比較之敘述，何者正確?","options":["前者能源耗用高，且產生較多污泥量","前者能源耗用低，且產生較多污泥量","後者每去除150kg COD約需0.5kg氮","前者每去除150kg COD約需5kg氮"],"answer":1,"category":"厭氧生物處理"},{"id":15,"question":"厭氧生物處理時，去除1公斤COD在標準狀態下可產生多少甲烷氣?","options":["0.01","0.8","0.35","0.55 m³"],"answer":3,"category":"厭氧生物處理"},{"id":16,"question":"好氧性生物是","options":["以NO3為氫接受者","以有機物為氫接受者","以為氫接受者","光合性微生物"],"answer":3,"category":"微生物與生物處理基礎"},{"id":17,"question":"有機性廢水之生物處理，最主要是依賴何種細菌","options":["自營性菌","光自營性菌","化學自營性菌","化學異營性菌"],"answer":4,"category":"微生物與生物處理基礎"},{"id":18,"question":"有機性廢水主要處理方法是?","options":["物理法","化學法","生物法","以上皆對"],"answer":3,"category":"微生物與生物處理基礎"},{"id":19,"question":"有機性廢水使用物化處理是針對?","options":["高濃度有機物","高濃度無機物","低濃度生物易分解有機物","低濃度生物無法分解有機物"],"answer":4,"category":"微生物與生物處理基礎"},{"id":20,"question":"有機性廢水處理系統中，前處理程序主要功能是?","options":["降低曝氣槽之有機負荷","輔助去除水溶性有機物","直接去除水溶性有機物","以上皆對"],"answer":1,"category":"活性污泥與操作控制"},{"id":21,"question":"有關污泥容積指標之敘述，何者錯誤?","options":["SVI太小則表示污泥太過緊密","為量測污泥沉降性之重要參數","SVI太大表示污泥沉降性及濃縮性不佳","當F/M過高及有特殊有毒工業廢水流入時，常使SVI值降低"],"answer":4,"category":"活性污泥與操作控制"},{"id":22,"question":"有關批式活性污泥法之敘述，何者錯誤?","options":["採用週期性進水與排水","基本概念是屬於時間導向之設計","污泥迴流效率比活性污泥法好","曝氣方式是屬於間歇式"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":23,"question":"有關活性污泥系統污泥沉澱池之敘述，何者正確?","options":["輔助去除非水溶性有機物","澄清及濃縮生物污泥","是調節出流固體物濃度之主要單元","用以沉澱原廢水之固體物"],"answer":2,"category":"活性污泥與操作控制"},{"id":24,"question":"有關氧化深渠法之敘述，何者正確?","options":["基本上屬於活性污泥法中之低有機負荷F/M之應用","基本上屬於活性污泥法中高F/M比之應用","基本上屬於接觸曝氣法之應用","以上皆非"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":25,"question":"有關氧化渠與氧化深渠之敘述，何者正確?","options":["深渠法之渠深較大，是因高效率的滾水機及曝氣器之使用","深渠法之渠深較大，是因適用於較低濃度之進流水","兩者渠深分別是3.5~4.0m與1.0-2.0m","以上皆對"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":26,"question":"有關微生物之新陳代謝之說明，正確者是","options":["合成作用可產生能量","合成作用得新細胞","分解作用可得新細胞","分解作用與代謝無關"],"answer":2,"category":"微生物與生物處理基礎"},{"id":27,"question":"有關厭氧濾床法之敘述，何者錯誤?","options":["微生物是屬於附著生長式","水流方向可採向上流或向下流方式","水力停留時間(HRT)可以加長至數十天，使處理效率提升","微生物生長係數小"],"answer":3,"category":"附著生長與生物膜"},{"id":28,"question":"有關懸浮生長與附著生長生物處理系統，何者之敘述是錯誤的?","options":["前者產生較少的污泥量","兩者皆有好氧與厭氧程序","後者通常不需污泥迴流","前者之微生物基質利用率較不受質量傳輸的限制"],"answer":1,"category":"附著生長與生物膜"},{"id":29,"question":"有關曝氣槽在活性污泥系統之功能是?","options":["調勻水量與水質","微生物分解有機物","將有機廢水、微生物充份混合","以上皆是"],"answer":4,"category":"活性污泥與操作控制"},{"id":30,"question":"可利用之有機物量與曝氣槽中微生物量之比值，為決定生物處理效率之最重要因子?","options":["溫度","毒性物質","食微比","微生物種類"],"answer":3,"category":"活性污泥與操作控制"},{"id":31,"question":"活性污泥中污泥是迴流到","options":["曝氣槽","前處理槽","污泥沉澱池","污泥消化槽"],"answer":1,"category":"活性污泥與操作控制"},{"id":32,"question":"活性污泥代謝之營養分，一般之[BOD5: N:P:Fe] 多少最為適當","options":["100: 1:5:0.7","100: 5:1:0.5","100:5:0.5:0.7","100:50:1:0.5"],"answer":2,"category":"活性污泥與操作控制"},{"id":33,"question":"活性污泥系統中，做迴流污泥之目的是?","options":["減少污泥產生量","維持曝氣槽之微生物濃度","維持污泥的排放量","以上皆非"],"answer":2,"category":"活性污泥與操作控制"},{"id":34,"question":"活性污泥系統中的曝氣槽，若進流污水量是200CMD，進流BOD是200mg/L，槽容積40m³，槽內MLVSS2，000mg/L，則食微比是多少(1/天)?","options":["0.2","0.32","0.4","0.5"],"answer":4,"category":"活性污泥與操作控制"},{"id":35,"question":"活性污泥系統之主要單元是","options":["前處理槽","調整槽","曝氣槽","沉澱池"],"answer":3,"category":"活性污泥與操作控制"},{"id":36,"question":"活性污泥系統設初沉池之功能是?","options":["穩定進流水質","穩定進流水量","降低次單元之有機負荷","提升微生物濃度"],"answer":3,"category":"活性污泥與操作控制"},{"id":37,"question":"活性污泥法中，曝氣槽內之污泥之MLVSS/MLSS值大約是?","options":["1.5","0.8","0.5","<0.5"],"answer":2,"category":"活性污泥與操作控制"},{"id":38,"question":"活性污泥法中的曝氣槽，若進流污水量2，000CMD，進流水BOD300mg/L，出流水BOD20mg/L，若每天廢棄污泥量是220kg乾污泥/天，則污泥產率(污泥/公斤BOD去除量)為","options":["0.2","0.4","0.8","1.0"],"answer":2,"category":"污泥處理與處置"},{"id":39,"question":"活性污泥法之活性污泥，最初營養階段之微生物是?","options":["變形蟲","變毛蟲","細菌","輪蟲"],"answer":3,"category":"活性污泥與操作控制"},{"id":40,"question":"活性污泥法判斷處理功能良好之指標生物是?","options":["變形蟲","細菌","輪蟲","藻類"],"answer":3,"category":"活性污泥與操作控制"},{"id":41,"question":"活性污泥法改良式的階梯曝氣法之特點是?","options":["混合液污泥可完全混合","曝氣槽內溶氧消耗與微生物群分佈均勻","可平衡有機負荷與需氧率","曝氣槽中之微生物進入"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":42,"question":"活性污泥處理系統，主要藉何種生長期之微生物來處理有機廢水?","options":["對數增殖期","加數增殖期","減率增殖期","減率增殖期至體內呼吸期"],"answer":4,"category":"活性污泥與操作控制"},{"id":43,"question":"活性污泥膜濾法(MBR)之商業系統多採橫流過濾，其原因是?","options":["固體物可在薄膜表面形成濾餅層，濾餅厚度大量增加","濾餅可以週期性快速移除","可避免薄膜表面積垢，可得最大滲透通量","可形成端點過濾的濾餅"],"answer":3,"category":"MBR 薄膜生物反應器"},{"id":44,"question":"活性污泥膜濾法(MBR)是利用薄膜取代傳統活性污泥法的何種設備?","options":["柵欄","沉澱池","曝氣槽","沉澱池與曝氣槽"],"answer":2,"category":"MBR 薄膜生物反應器"},{"id":45,"question":"氧化渠之渠道水流速控制在45cm/sec左右，目的是","options":["增加處理流量","保持渠內物質之混合懸浮移動","保持渠內污泥快速流入終沉池","以上皆是"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":46,"question":"常用生物處理程序包括?","options":["活性污泥法","接觸曝氣法","厭氧濾床法","以上皆對"],"answer":4,"category":"微生物與生物處理基礎"},{"id":47,"question":"接觸曝氣法之充填率是50~60%，目的是?","options":["配合進流水濃度","配合曝氣設備","配合進流水濃度、曝氣設備與出流水濃度","不使生物膜過分蓄積而產生阻塞問題"],"answer":4,"category":"附著生長與生物膜"},{"id":48,"question":"接觸曝氣法之敘述中何者正確?","options":["接觸材表面應該避免附著生長生物膜","此法是屬於生物膜法之一種","此法是屬於活性污泥法之一種","此法有內建之沉澱構造"],"answer":2,"category":"附著生長與生物膜"},{"id":49,"question":"曝氣槽中活性污泥成熟期時，何種微生物佔優勢?","options":["鞭毛蟲","細菌","纖毛蟲","吸管蟲"],"answer":3,"category":"活性污泥與操作控制"},{"id":50,"question":"接觸曝氣處理若有發現生物膜嚴重脫落，污泥有上浮情形，其異常原因分析為","options":["進水含有毒性物質","過度曝氣","有機負荷過低","進水有機物濃度下降"],"answer":1,"category":"附著生長與生物膜"},{"id":51,"question":"傳統式活性污泥法處理程序中，生物槽之功能是?","options":["將廢水和活性污泥充分混合曝氣","將活性污泥與廢水分開","迴流生物污泥","以上皆非"],"answer":1,"category":"活性污泥與操作控制"},{"id":52,"question":"傳統活性污泥法(AS)與活性污泥膜濾系統(MBR)比較，何者正確?","options":["前者會消耗較多能源","後者會產生大量污泥","前者污泥濃度高反應快","後者可大幅節省空間"],"answer":4,"category":"MBR 薄膜生物反應器"},{"id":53,"question":"微生物之主要構成元素是?","options":["N、P、S","C、H、O","Na、K、Ca","Mg、Fe"],"answer":2,"category":"微生物與生物處理基礎"},{"id":54,"question":"接觸穩定法若BOD之去除率太低，以致於短時間內不能達到所欲之總去除率時，則應採取下列哪種措施以達到需求?","options":["延長接觸時間","縮短接觸時間","縮短穩定時間","延長穩定時間"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":55,"question":"厭氧生物處理系統中，增加污泥停留時間(SRT)之主要目的是?","options":["減少水力停留時間","使酸生成菌生長及反應","使甲烷生成菌生長及反應","使污泥進入內呼吸期"],"answer":3,"category":"厭氧生物處理"},{"id":56,"question":"依據水質檢驗結果，調整曝氣槽操作控制條件，以維持正常運轉，其控制指標應包括下列何者?","options":["SVI","食微比(F/M)","污泥停留時間及迴流污泥量","以上皆是"],"answer":4,"category":"活性污泥與操作控制"},{"id":57,"question":"廢水之好氧性處理之反應過程為[有機物+?+微生物→增殖生物+CO2+H2O+NO3-+SO42-]請問?應該是何物?","options":["細菌","氧","氧化劑","混凝劑"],"answer":2,"category":"微生物與生物處理基礎"},{"id":58,"question":"廢水之厭氧生物處理，其第一階段是?","options":["甲烷形成菌產生有機酸","甲烷形成菌利用有機酸","酸形成菌產生有機酸","有機酸被酸形成菌利用"],"answer":3,"category":"厭氧生物處理"},{"id":59,"question":"廢水生物處理系統一般最佳範圍介於多少之間?","options":["2.5-3.5","4.5-5.5","6.5~7.5","8.5-9.5"],"answer":3,"category":"微生物與生物處理基礎"},{"id":60,"question":"影響厭氧生物處理之重要操作指標是?","options":["甲烷產量","二氧化碳產量","pH與營養物質","污泥停留時間(SRT)"],"answer":4,"category":"厭氧生物處理"},{"id":61,"question":"以下何者不是影響厭氧生物處理系統穩定的物理因子","options":["污泥停留時間","揮發酸","攪拌","溫度"],"answer":2,"category":"厭氧生物處理"},{"id":62,"question":"標準活性污泥法之SVI，下列敘述何者正確?","options":["SVI越小越好，有利操作","50~150mL/g是良好之污泥","SVI越大越好","200mL/g是良好之污泥"],"answer":2,"category":"活性污泥與操作控制"},{"id":63,"question":"以下何系統為槽內溶氧消耗和微生物群可均勻分佈的活性污泥法，且其優點為減少突增與尖峰濃度?","options":["柱塞流型反應系統","完全混合型反應系統","接觸穩定法","延長曝氣法"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":64,"question":"某廠進流廢水量2，000m³/day，進水BOD為300mg/L，曝氣池容積600m³，MLVSS濃度2，500mg/L，請估算F/M值?","options":["0.2","0.4","0.8","1.0"],"answer":2,"category":"活性污泥與操作控制"},{"id":65,"question":"以下何者是活性污泥處理污泥變白可能之原因","options":["絲狀菌或固著型纖毛蟲大量繁殖","進水負荷過高，有機物分解不全","進水中洗滌劑含量過高","曝氣池供氧不足，DO值低"],"answer":1,"category":"活性污泥與操作控制"},{"id":66,"question":"生物處理若依有無供給氧氣情況，可分為幾種處理程序，下列何者不屬於其分類方式?","options":["好氧性","兼氧性","厭氧性","附著性"],"answer":4,"category":"微生物與生物處理基礎"},{"id":67,"question":"活性污泥微生物代謝所需之[BOD5:N:P:Fe]之比例，下列何者為最適當?","options":["100:5:10:0.5","10:5:1:5","200:5:1:0.5","100:5:1:0.5"],"answer":4,"category":"活性污泥與操作控制"},{"id":68,"question":"下列何者不屬於活性污泥系統基本單元?","options":["反沖洗設備","迴流污泥設備與排泥設備","污泥沉澱池","曝氣槽"],"answer":1,"category":"活性污泥與操作控制"},{"id":69,"question":"有關活性污泥系統曝氣槽之敘述，下列何者錯誤?","options":["MLSS約為1，500~3，000mg/L","可藉量測攝氧率判定微生物活性","溶氧保持在1~3mg/L","槽中厭氧性微生物利用廢水有機物為食物，進行生物氧化作用"],"answer":4,"category":"厭氧生物處理"},{"id":70,"question":"有關活性污泥系統有機負荷之敘述，下列何者錯誤?","options":["或稱為F/M(食微比)","單位為kg BOD5/(kg MLVSS. day)","標準活性污泥法之F/M約0.2-0.5kg","計算式F/M BOD/MLVSS"],"answer":4,"category":"活性污泥與操作控制"},{"id":71,"question":"生物處理方法中下列何者屬於懸浮生長式?","options":["滴濾池法","接觸曝氣法","氧化深渠","生物圓盤法"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":72,"question":"有關活性污泥曝氣方法之敘述，下列何者錯誤?","options":["水動式剪力裝置產生氣泡屬表面曝氣裝置","常用之設備有散氣曝氣及表面曝氣裝置","表面曝氣分輪刷式與葉輪式","表面曝氣裝置是由輪葉將廢水噴出成薄片狀或水滴狀以完成輸氣過程"],"answer":1,"category":"活性污泥與操作控制"},{"id":73,"question":"有關MBR與傳統活性污泥程序相比之敘述，下列何者正確?","options":["無法去除細菌和病毒，故無消毒作用","MBR維持高F/M比，減少廢棄污泥量","MBR能耗低，但需外加化學藥劑","MBR污泥濃度高，可減少處理槽體積"],"answer":4,"category":"MBR 薄膜生物反應器"},{"id":74,"question":"有關MBR與傳統活性污泥程序相比之敘述，下列何者錯誤?","options":["MBR可縮短污泥停留時間","MBR污泥可完全截留","MBR初設成本較高，但操作成本低","MBR適合中小型規模特殊污染物處理"],"answer":1,"category":"MBR 薄膜生物反應器"},{"id":75,"question":"有關氧化渠之敘述，下列何者錯誤?","options":["由池深約的溝渠連結成環狀或帶狀","需控制管道水流速約在30cm/sec以下","以旋轉滾輪曝氣機曝氣將氧氣帶入混合液中","氧化渠法通常不須設置初沉池"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":76,"question":"對於使用小型轉輪的氧化渠渠深為","options":["1.0-2.0","10~20","0.1-0.2","2.5-3.5m"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":77,"question":"有關氧化渠之特性，下列何者錯誤?","options":["不需初沉池，可減少建造費","所需處理用地較大","水深為1.2~1.6m","具有較大的緩衝容量，受水質水量負荷之影響較大"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":78,"question":"氧化深渠，渠深為?","options":["1.0-2.0","5-6","3.5-4.0","7~9 m"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":79,"question":"接觸曝氣槽一般槽數為?","options":["2~3槽","20-30槽","單槽","5槽以上"],"answer":1,"category":"附著生長與生物膜"},{"id":80,"question":"接觸曝氣槽之接觸材料不具有下列哪一項特性?","options":["材料具機械強度","孔隙率小","生物膜容易附著","比表面積大"],"answer":2,"category":"附著生長與生物膜"},{"id":81,"question":"有關接觸曝氣法缺點之敘述，下列何者正確?","options":["高BOD負荷下會造成阻塞","附著之生物膜量不易調節","剝落之生物膜在終沉池中不易沉澱","以上皆是"],"answer":4,"category":"附著生長與生物膜"},{"id":82,"question":"下列何者不屬於接觸曝氣法曝氣攪拌方式?","options":["單側曝氣","中心曝氣","全面曝氣","豎軸曝氣"],"answer":4,"category":"附著生長與生物膜"},{"id":83,"question":"有關活性污泥系統設計及操作標準之敘述，下列何者錯誤?","options":["迴流污泥量與流入廢水量之比率稱為污泥食微比","污泥齡係微生物(污泥)在系統中之平均停留時間","標準活性污泥法曝氣槽內之MLSS約在1，500-3，000mg/L間","污泥齡也稱為平均細胞停留時間"],"answer":1,"category":"活性污泥與操作控制"},{"id":84,"question":"有關SBR反應階段操作之敘述，下列何者錯誤?","options":["可進行污泥廢棄，控制污泥齡","可同時進行有機物去除與硝化作用","廢水完全硝化後，不可降低溶氧","廢水完全硝化後，可利用初沉污泥或外加碳源達到脫氮"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":85,"question":"有關污泥容積指標之敘述，下列何者錯誤?","options":["50mL/g以下表嚴重膨化","標準活性污泥法之污泥容積指標介於50~150mL/g","簡稱SVI","若SVI太小，易造成排泥困難及阻塞污泥管線"],"answer":1,"category":"微生物與生物處理基礎"},{"id":86,"question":"有關單槽連續進流SBR之敘述，下列何者正確?","options":["進流是間歇式，但反應與排水式連續式","係採高負荷的高率曝氣法","可能會有發生短流的現象","槽內稀釋能力相當低"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":87,"question":"厭氧生物處理技術中，不需填充料但仍可固定生物細胞的反應器為?","options":["厭氧接觸法","上流式厭氧污泥床法","厭氧濾床法","厭氧流體化床法"],"answer":2,"category":"附著生長與生物膜"},{"id":88,"question":"批式活性污泥法影響SBR操作之因素中依其進流時間/反應時間操作條件，比較耗氧率與污泥沉降性，以下哪一個比值的沉降速率最佳","options":["2/4","4/2","5/1","1/3"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":89,"question":"較經濟且適合甲烷菌進行厭氧反應之溫度操作範圍為?","options":["中溫20~30℃","高溫65~75℃","中溫30~38℃","高溫60~70℃"],"answer":3,"category":"厭氧生物處理"},{"id":90,"question":"有關厭氧生物處理化學因子之敘述，下列何者錯誤?","options":["揮發酸為厭氧酸生成相的產物","揮發酸不是甲烷化的先驅物質","鹼度不足時，可添加化學藥品以提高鹼度","揮發酸快速累積時，將導致pH降低"],"answer":2,"category":"厭氧生物處理"},{"id":91,"question":"有關厭氧生物處理方法缺點之敘述，下列何者錯誤?","options":["低的污泥產生量其起動時間較長","一旦出問題系統復原所需時間較長","低濃度的廢水使反應槽中的微生物不易維持高的濃度","對抑制性及毒性物質較不敏感"],"answer":4,"category":"厭氧生物處理"},{"id":92,"question":"一般好氧系統，微生物生長係數(Y值)在多少左右?","options":["0.2~0.4","0.4-0.6","4.0-6.0","2.0~4.0"],"answer":2,"category":"微生物與生物處理基礎"},{"id":93,"question":"有關細菌之生長與死亡之敘述，下列何者正確?","options":["減率增殖期菌數減少進入死亡期","體內呼吸期菌數成長快速且呈對數增加之情形","對數增殖期菌體分裂增殖之速率減緩","體內呼吸期菌數減少"],"answer":4,"category":"微生物與生物處理基礎"},{"id":94,"question":"有關厭氧濾床法優點之敘述，下列何者錯誤?","options":["不需污泥迴流即能得到很長的SRT","水力停留時間HRT可以延長","微生物生長係數小","能忍受較大的負荷變化"],"answer":2,"category":"附著生長與生物膜"},{"id":95,"question":"有關厭氧濾床法缺點之敘述，下列何者錯誤?","options":["容易堵塞","只適用處理溶解性有機物廢水","若廢水SS高，必須先用前處理單元去除","無法忍受較大的負荷變化及溫度等環境變化"],"answer":4,"category":"附著生長與生物膜"},{"id":96,"question":"有關厭氧流體化床反應器優點之敘述，下列何者錯誤?","options":["活性生物濃度高，可縮短生物反應時間","對於突增負荷或溫度改變所產生之影響較少","處理容量的擴充受限制","減少反應槽體積及用地面積"],"answer":3,"category":"附著生長與生物膜"},{"id":97,"question":"有關厭氧流體化床反應器缺點之敘述，下列何者錯誤?","options":["需要均勻的水流分散設備","操作管理需要較高的技術","迴流率大，動力需求較大","生物膜生長速率快，啟動時間短"],"answer":4,"category":"附著生長與生物膜"},{"id":98,"question":"一般氨氮之生物去除程序包括?","options":["厭氧消化","消化及脫硝","硝化及脫硝","好氧消化"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":99,"question":"有關生物除磷之敘述，下列何者錯誤?","options":["促進系統中磷蓄積菌之生長來攝取水中之正磷酸鹽","釋磷後生物污泥之攝磷率降低","可先使污泥厭氧釋磷，再用石灰將磷酸鹽沉除","廢水中磷多以磷酸鹽及多磷酸鹽存在"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":100,"question":"有關廢水生物處理系統之敘述，下列何者錯誤?","options":["pH影響酵素的活性","細菌為主的系統於中性時生長較佳","藻類與真菌於略鹼性時生長較佳","一般最佳範圍介於6.5與7.5間"],"answer":3,"category":"微生物與生物處理基礎"},{"id":101,"question":"厭氣接觸法用以提高SRT/HRT比值之方法，下列何者正確","options":["增加回流水","增加污泥迴流","將填充料置入於反應器內","固定生物細胞"],"answer":2,"category":"厭氧生物處理"},{"id":102,"question":"污泥之沉降性以污泥容積指標表示之，簡稱為何?","options":["FI","CI","SDI","SVI"],"answer":4,"category":"活性污泥與操作控制"},{"id":103,"question":"在無氧環境下，大腸菌可將葡萄糖發酵為CO2和","options":["有機酸","水","氮氣","氨"],"answer":1,"category":"微生物與生物處理基礎"},{"id":104,"question":"下列何者不是厭氧生物處理系統之缺點?","options":["無法忍受衝擊性的高有機物負荷","由於低的污染物去除速率及低的污泥產生量，啟動時間較長","處理低濃度的有機廢水較不經濟","對一些抑制性及毒性物質敏感"],"answer":1,"category":"厭氧生物處理"},{"id":105,"question":"下列何種處理程序具破壞揮發性有機固體物以達到污泥減量的效果，並改善脫水性?","options":["調理","消化","堆肥","以上皆非"],"answer":2,"category":"污泥處理與處置"},{"id":106,"question":"下列氧化渠處理廢水特性，何者錯誤?","options":["屬於低有機負荷之應用","渠道水流還需控制在55cm/sec以上","不需設置初沉池，減少建造費","所需用地面積大"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":107,"question":"當廢水含大量懸浮狀態BOD時，下列何者最為適用?","options":["接觸穩定法","接觸曝氣法","階梯曝氣法","延長曝氣法"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":108,"question":"下列有關支流式及浸入式MBR特性比較之敘述，何者錯誤?","options":["浸入式MBR之通量較低","浸入式MBR在積垢控制上較容易","浸入式MBR在改裝方便性上較不容易","浸入式MBR在操作彈性上較受限"],"answer":2,"category":"MBR 薄膜生物反應器"},{"id":109,"question":"好氧消化較厭氧消化之優勢中，以下敘述何者為非?","options":["揮發性固體物之減少量大於厭氧消化","上澄液BOD濃度較低","產生較無臭、腐植狀、生物性穩定之最終產物","產生之污泥脫水性良好"],"answer":1,"category":"厭氧生物處理"},{"id":110,"question":"影響硝化反應之因子何者敘述有誤?","options":["當溫度低於10℃時，硝化菌將停止作用","當溫度低於15℃，則硝化速率迅速降低，易出現亞硝酸鹽的累積","pH值低於6或高於9.6時，硝化反應將停止進行","一般而言，當溶氧濃度低時，硝化反應受溶氧濃度之影響大"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":111,"question":"單側曝氣方式的矩形接觸曝氣槽，其水深與槽寬的比值，下列何者正確?","options":["1:1.3以下","1:2.5以下","1:3.5以下","1:4.5以下"],"answer":1,"category":"附著生長與生物膜"},{"id":112,"question":"以細菌質量表示，細菌生長曲線可分為三個階段，其順序下列何者正確?A.對數增殖期;B.體內呼吸期;C.減率增殖期","options":["C、A、B","A、B、C","B、A、C","A、C、B"],"answer":4,"category":"微生物與生物處理基礎"},{"id":113,"question":"可作為污泥調理時加藥量之指標為何?","options":["污泥之濃度","污泥之體積","污泥之pH值","污泥之界達電位"],"answer":4,"category":"污泥處理與處置"},{"id":114,"question":"下列有關單槽連續進流SBR之敘述，何者錯誤?","options":["污泥無需迴流","污泥在幾乎完全靜止中沉澱","不具處理N、P之功能","有機負荷為均一、水力負荷為週期變化"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":115,"question":"接觸曝氣槽較佳之接觸材料應有之特性，下列何者錯誤?","options":["強度高","比重大","孔隙率大","比表面積大"],"answer":2,"category":"附著生長與生物膜"},{"id":116,"question":"有關影響活性污泥處理效率之有害物質敘述，下列何者錯誤?","options":["消毒劑不會造成活性污泥解體","當混合液中有硫化物出現時，廢水呈厭氧作用","H2S若超過5mg/L，亦會造成污泥解體","廢水中重金屬含量變化大時，對活性污泥凝聚作用將造成影響"],"answer":1,"category":"活性污泥與操作控制"},{"id":117,"question":"厭氧處理程序主要氣體產物，下列何者正確?","options":["CH4、SO42-","CO2、SO42-","CH4、CO2","CO2、NO3-"],"answer":3,"category":"厭氧生物處理"},{"id":118,"question":"厭氣消化在那個階段後廢水達到穩定?","options":["水解","酸化","甲烷化","以上皆非"],"answer":3,"category":"厭氧生物處理"},{"id":119,"question":"污泥含水率之計算時所使用之乾污泥重是在多少溫度下乾燥後的污泥重?","options":["自然乾燥","103℃","550℃","以上皆非"],"answer":2,"category":"污泥處理與處置"},{"id":120,"question":"厭氧濾床由於消化完全，其微生物生長係數(Y值)在多少以下?","options":["1","0.1","0.01","0.001"],"answer":3,"category":"附著生長與生物膜"},{"id":121,"question":"典型水處理廠各單元所產生之污泥種類有下列幾種: A.生物污泥 B.化學污泥 C.浮渣 D.砂礫 E.菜渣，何者為正確?","options":["A、B","A、B、C","A、B、C、D","A、B、C、D、E"],"answer":4,"category":"微生物與生物處理基礎"},{"id":122,"question":"好氧與厭氧處理程序之比較何者錯誤?","options":["能源耗用方面，好氧程序較高","去除單位COD之生成物，好氧生成污泥率較低","主要最終產物方面，好氧程序包括SO42-、NO3-","營養需求方面，好氧程序較高"],"answer":2,"category":"厭氧生物處理"},{"id":123,"question":"多孔性擔體上成長大量微生物，反應槽具有那些優點，以下敘述何者有誤","options":["高磨耗","高負荷","高效率","高穩定性"],"answer":1,"category":"附著生長與生物膜"},{"id":124,"question":"SBR排泥頻率為何?","options":["每天循環一次","一個月一次","三個月一次","每天循環一次至三個月一次皆可"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":125,"question":"懸浮生長與附著生長生物處理系統比較何者正確?","options":["懸浮生長微生物懸浮在反應槽內","附著生長對進流水中毒性物質相當敏感","懸浮生長基質利用率受質量傳輸的影響顯著","附著生長污泥產生量較多"],"answer":1,"category":"附著生長與生物膜"},{"id":126,"question":"下列敘述何者錯誤?","options":["傳統式活性污泥法可分為柱塞型和完全混合型","接觸穩定法利用生物吸附去除大量BOD","階梯曝氣法分數處進流廢水，以平衡有機負荷及需氧率","延長曝氣法使微生物進入對數生長期"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":127,"question":"甲烷生成菌為厭氧菌，在攝氏幾度左右其厭氧反應作用就會受到抑制而減緩?","options":["30℃","20℃","50℃","60℃"],"answer":2,"category":"厭氧生物處理"},{"id":128,"question":"各類微生物均有一最佳生長溫度範圍之敘述，下列何者錯誤?","options":["低溫細菌最佳溫度12~18℃","中溫細菌，生長範圍10~45℃","中溫細菌最佳溫度為37~45℃","高溫細菌最佳溫度55~65℃"],"answer":3,"category":"微生物與生物處理基礎"},{"id":129,"question":"厭氧消化最主要的目的是將有機物質穩定化，而欲使消化槽之操作穩定，下列何者不是主要影響消化效率之因子?","options":["良好的攪拌","消化槽有效深度","維持足夠長的污泥停留時間(SRT)","最佳的環境條件"],"answer":2,"category":"厭氧生物處理"},{"id":130,"question":"污泥消化之過程可分為哪三個階段，以下何者有誤?","options":["酸化","甲烷化","水解","以上皆非"],"answer":4,"category":"污泥處理與處置"},{"id":131,"question":"下列有關活性污泥法曝氣設備之敘述，何者錯誤?","options":["曝氣設備主要功用之一是維持生物固體於曝氣槽中呈懸浮狀態","大氣泡散氣裝置之輸氧效率較小氣泡為佳","表面曝氣裝置是由輪葉將廢水噴出成薄片狀或水滴狀以完成輸氧過程","表面曝氣裝置之輸氧效率與驅輪在液面下之沉入度、轉速及轉輪直徑相關"],"answer":2,"category":"活性污泥與操作控制"},{"id":132,"question":"下列何者不屬於活性污泥之微生物?","options":["原生動物","少量真菌","細菌","甲烷菌"],"answer":4,"category":"厭氧生物處理"},{"id":133,"question":"污泥顆粒大小及形狀依處理程序有很大之變化，下列敘述何者正確?","options":["顆粒大對消化有利","顆粒小有利於脫水","顆粒小有利於沉降脫水","以上皆非"],"answer":4,"category":"微生物與生物處理基礎"},{"id":134,"question":"有關厭氧生物處理方法優點之敘述，下列何者錯誤?","options":["長時間不供應有機物，厭氧菌即自動死亡","可忍受衝擊性的高有機物負荷","無機營養物質(如氮和磷)需要量較少","產生的污泥較少"],"answer":1,"category":"厭氧生物處理"},{"id":135,"question":"以下何者不是消化污泥之性質","options":["變白","外表凹凸不平","污泥容易脫水","體積減少"],"answer":1,"category":"污泥處理與處置"},{"id":136,"question":"SBR每槽循環可分為哪5個階段?","options":["沉降、進流、反應、排水、靜置","進流、反應、沉降、排水、靜置","進流、沉降、排水、反應、靜置","排水、進流、反應、沉降、靜置"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":137,"question":"有關厭氧生物處理基本原理之敘述，下列何者錯誤?","options":["厭氧過程分酸性消化和甲烷化階段","酸形成菌將複雜的有機物水解發酵成簡單有機酸","甲烷形成菌將有機酸轉化成甲烷及CO2","如果累積低分子量有機酸，將強化甲烷生成"],"answer":4,"category":"厭氧生物處理"},{"id":138,"question":"有關厭氧濾床法之敘述，下列何者錯誤?","options":["可維持高濃度微生物於反應槽中","水流方向有向上流及向下流兩種","不需污泥迴流即能維持長SRT","可以延長水力停留時間"],"answer":4,"category":"附著生長與生物膜"},{"id":139,"question":"有關接觸曝氣法優點之敘述，下列何者錯誤?","options":["比表面積較大，可保持大量之生物膜","附著之微生物污泥齡長","不需污泥迴流即能維持長SRT","污泥產生量多"],"answer":4,"category":"附著生長與生物膜"},{"id":140,"question":"活性污泥膜濾法(MBR)與傳統活性污泥程序(AS)之特性比較，下列何者正確?","options":["MBR空間需求較小","MBR污泥濃度較低","MBR會產生大量污泥","MBR在能源消耗上較低"],"answer":1,"category":"MBR 薄膜生物反應器"},{"id":141,"question":"活性污泥膜濾法(MBR)處理廢水具有不少優點，但尚待克服之問題為?","options":["污泥濃度太高","污泥停留時間太長","去除細菌及病媒效率低","能源消耗量較活性污泥法為高"],"answer":4,"category":"MBR 薄膜生物反應器"},{"id":142,"question":"標準活性污泥法及階梯曝氣法之MLSS大都在多少mg/L之範圍?","options":["500~1，000","1，500-3，000","5，000-6，000","7，000~10，000"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":143,"question":"氧化渠處理流程及單元與傳統活性污泥系統之不同處為","options":["終沉池污泥無迴流","無設置初沉池","無設置終沉池","處理流程與單元均相同"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":144,"question":"細菌的生長曲線中，那一期細菌分裂最旺盛?","options":["遲滯期","對數增殖期","減率增殖期","體內呼吸期"],"answer":2,"category":"微生物與生物處理基礎"},{"id":145,"question":"細菌生長過程中，下列哪一期是細菌在形態、生理特徵、化學組成及代謝作用上最一致，常用來作為細菌生理實驗?","options":["遲滯期","對數增殖期","減率增殖期","體內呼吸期"],"answer":2,"category":"微生物與生物處理基礎"},{"id":146,"question":"活性污泥中，何種單元系統為有機物分解的主要場所?","options":["最初沉澱槽","最後沉澱槽","放流槽","曝氣槽"],"answer":4,"category":"活性污泥與操作控制"},{"id":147,"question":"活性污泥係由異種個體群微生物所構成之混合培養體，以下何者有誤?","options":["細菌","酵母","原生動物","少量真菌"],"answer":2,"category":"活性污泥與操作控制"},{"id":148,"question":"在有氧環境下，大腸菌可將葡萄糖分解為CO2和","options":["有機酸","水","氮氣","氨"],"answer":2,"category":"微生物與生物處理基礎"},{"id":149,"question":"以下何種是屬於附著生長式?","options":["活性污泥法","生物圓盤法","滴濾法","接觸曝氣法"],"answer":4,"category":"附著生長與生物膜"},{"id":150,"question":"以下對於懸浮生長式的特色何者有誤?","options":["污泥產量較多","微生物基質利用率較不受質量傳輸的限制","對進流水中毒性物質較能忍受","微生物懸浮在反應槽內"],"answer":3,"category":"微生物與生物處理基礎"},{"id":151,"question":"下列有關活性污泥法基本原理之敘述，何者有誤?","options":["在曝氣槽中，藉曝氣設備供給氧氣及混合","溶解性無機物被曝氣槽中微生物分解去除","活性污泥混合液送至沉澱池予以固液分離","迴流污泥以控制曝氣槽中足夠之污泥濃度"],"answer":2,"category":"活性污泥與操作控制"},{"id":152,"question":"下列敘述何者正確? A.上流式厭氧污泥床(UASB)法微生物生長方式是屬附著生長式 B.薄膜生物處理法(MBR)微生物生長方式是屬懸浮生長式 C.厭氧濾床法微生物生長方式是屬附著生長式","options":["僅A、B","僅B、C","僅A、C","A、B、C"],"answer":3,"category":"MBR 薄膜生物反應器"},{"id":153,"question":"影響硝化反應之因子何者敘述有誤?","options":["最適合硝化反應的溫度為30~35℃","最佳pH範圍為7.5-8.5","通常維持水中溶氧濃度為2~3mg/L","通常污泥齡須維持在5天左右"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":154,"question":"何種生物處理程序可進行脫硝?","options":["活性污泥法","氧化渠","接觸曝氣法","厭氣接觸系統"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":155,"question":"自營性菌生長所需的碳源?","options":["有機化合物","無機化合物","CH4","二氧化碳"],"answer":4,"category":"微生物與生物處理基礎"},{"id":156,"question":"接觸曝氣槽以下列何者形狀之接觸材料，捕捉懸浮物質之能力較佳?","options":["繩狀物","波浪板狀","(懸浮+附著)生長式","粒狀體"],"answer":4,"category":"附著生長與生物膜"},{"id":157,"question":"接觸曝氣法在操作管理上最大的問題是接觸材的甚麼問題?","options":["吸附","吸收","阻塞","脫落"],"answer":3,"category":"附著生長與生物膜"},{"id":158,"question":"關於活性污泥法，下列敘述何者有誤?","options":["為厭氧處理程序","係由好氧性細菌、原生動物等微生物、溶解性有機物及被吸附的懸浮物質所形成","具有吸附、氧化廢(污)水中的有機物，使達到安定化的機能","廢水在適當之pH、溫度及食微比條件下，經由強制曝氣提供廢(污)水中之溶氧，使微生物被活化而淨化水質之方法"],"answer":1,"category":"厭氧生物處理"},{"id":159,"question":"傳統活性污泥廢水處理系統於正常操作狀態下，活性污泥中出現之原生動物總類以下列何者為優勢種?","options":["鞭毛蟲","變形蟲","自由游泳纖毛蟲","輪蟲"],"answer":4,"category":"活性污泥與操作控制"},{"id":160,"question":"活性污泥系統最重要之兩個操作參數為何? A.食微比 B.曝氣量 C.水力停留時間 D.污泥停留時間","options":["A、B","A、D","B、C","C、D"],"answer":2,"category":"活性污泥與操作控制"},{"id":161,"question":"廢水處理廠生物曝氣槽中，正常活性污泥之污泥容積指數(SVI)範圍為:","options":["10~40","50-150","160-300","300以上"],"answer":2,"category":"活性污泥與操作控制"},{"id":162,"question":"廢水處理廠在良好操作狀態下，活性污泥生物相是以何類生物為指標?","options":["細菌類","纖毛蟲類","鞭毛蟲類","真菌類"],"answer":2,"category":"活性污泥與操作控制"},{"id":163,"question":"廢水生物處理系統中主要的硝化作用為?","options":["自營性硝化作用","異營性硝化作用","以上皆非","以上皆是"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":164,"question":"以下敘述何者正確?","options":["光合自營菌之碳源為CO2","光合自營菌之電子供給者為有機物","化學自營菌之碳源為有機物","化學異營菌之碳源為CO2"],"answer":1,"category":"微生物與生物處理基礎"},{"id":165,"question":"硝化菌屬於以下何者細菌?","options":["光合自營性菌","化學自營性菌","光合異營性菌","化學異營性菌"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":166,"question":"絲狀菌是屬於","options":["好氧異營菌","好氧自營菌","厭氧異營菌","厭氧自營菌"],"answer":1,"category":"活性污泥與操作控制"},{"id":167,"question":"細菌生長曲線中，那一階段細菌的生長與體內呼吸期速率約略相等","options":["遲滯期","對數期","減率增殖期","以上皆非"],"answer":3,"category":"微生物與生物處理基礎"},{"id":168,"question":"在曝氣槽中，使有機廢水、微生物與氧充分混合，而達到去除有機物的目的者為","options":["氧化池法","活性污泥法","散水濾床法","生物旋轉盤法"],"answer":2,"category":"活性污泥與操作控制"},{"id":169,"question":"接觸曝氣法反沖洗之時機，不正確者為","options":["曝氣槽內接觸材料水位上升","曝氣槽內有白色污泥存在","曝氣槽內SS濃度增加","曝氣槽內有黑色異味之SS出現"],"answer":2,"category":"附著生長與生物膜"},{"id":170,"question":"以下何者達同樣功能僅須標準活性污泥法的 1/3-1/4 佔地面積，不須迴流污泥，適用於既有池體擴建且用地狹小的廢水處理廠","options":["批式活性污泥法","氧化渠","接觸曝氣法","流體床固定生物膜法"],"answer":4,"category":"附著生長與生物膜"},{"id":171,"question":"活性污泥法中迴流污泥之主要目的在於","options":["增加SS去除率","穩定F/M比","增加曝氣時間","增加廢水處理量"],"answer":2,"category":"活性污泥與操作控制"},{"id":172,"question":"標準活性污泥法之污泥容積指標SVI 應控制在","options":["1，000","300","500","100mL/g左右"],"answer":4,"category":"活性污泥與操作控制"},{"id":173,"question":"典型活性污泥之水分分佈，其中哪種水分需藉壓密或機械脫水始可去除?","options":["毛細管結合水","間隙水","內部水","表面附著水"],"answer":1,"category":"污泥處理與處置"},{"id":174,"question":"氧化渠法與下列哪種處理法之理論相似?","options":["接觸穩定法","延長曝氣法","接觸曝氣法","階梯曝氣法"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":175,"question":"污水處理方法中，利用好氧生物分解複雜有機物所得之最終產物為何?","options":["甲烷","有機酸","一氧化碳","二氧化碳"],"answer":4,"category":"微生物與生物處理基礎"},{"id":176,"question":"為使曝氣槽內混合液之氧利用量均勻化，將狹長之曝氣槽分成數處，分別流入污水之活性污泥法稱為","options":["階梯曝氣法","延長曝氣法","氧化渠法","批次活性污泥法"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":177,"question":"下列何者為食微比的單位?","options":["無單位","kg BOD5/kg MLVSS. day","kg BOD5/kg SS. m³","kg SS/kg COD. m³"],"answer":2,"category":"活性污泥與操作控制"},{"id":178,"question":"對於污水處理過程中所產生的污泥之正確處理流程為何?","options":["污泥濃縮→污泥消化→污泥脫水","污泥脫水→污泥濃縮→污泥消化","污泥濃縮→污泥脫水→污泥消化","污泥脫水→污泥消化→污泥濃縮"],"answer":1,"category":"污泥處理與處置"},{"id":179,"question":"有關生物脫硝作用，下列敘述何者正確?","options":["產生氨氮","不會消耗鹼度","無需提供碳源","需於好氧環境下進行"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":180,"question":"在水體中的含氮污染物主要以有機氮及無機氮兩種形式存在，以下何者不屬於無機氮","options":["氨氮","亞硝酸鹽","硝酸鹽氮","尿素"],"answer":4,"category":"微生物與生物處理基礎"},{"id":181,"question":"關於污水的好氧生物處理何者正確?","options":["利用好氧微生物，將有機污染物氧化分解成較穩定的有機物","利用好氧微生物，將無機污染物氧化轉化成較穩定的有機物","利用好氧微生物，將有機污染物氧化分解成較穩定的無機物","利用好氧微生物，將無機污染物氧化分解成較穩定的無機物"],"answer":3,"category":"微生物與生物處理基礎"},{"id":182,"question":"好氧生物處理批式活性污泥法影響操作之因素，以下敘述何者有誤?","options":["降低溶氧可增加有機物之去除","高污泥濃度可降低F/M比","COD去除率在高MCRT時，去除率較高","進流時間/反應時間比在2/4者沉降速率最佳，此與槽中最大基質濃度有關"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":183,"question":"第一代反應器為家庭化糞池，屬於無污泥迴流、連續攪拌型式，其SRT/HRT(污泥停留時間/水力停留時間)比值為","options":["0.5","1.2","0.7","1"],"answer":4,"category":"微生物與生物處理基礎"},{"id":184,"question":"污泥厭氧消化下列何者不是其優點?","options":["污泥質量削減","產生沼氣","甲烷菌反應快","可改善污泥脫水"],"answer":3,"category":"厭氧生物處理"},{"id":185,"question":"下列有關上流式厭氧污泥床(UASB)與標準活性污泥法(AS)之特性比較敘述，何者正確?","options":["有機負荷:UASB>AS","污泥產生率:UASB>AS","土地需求:UASB>AS","供氧動力需求:UASB>AS"],"answer":1,"category":"厭氧生物處理"},{"id":186,"question":"下列Carrousel 氧化深渠反應槽設計內容，何者錯誤?","options":["輸氣量和葉片浸水深成正比","葉片浸水深僅由溢流堰高度來調整","只能安裝於氧化渠一端水流轉彎處","除導流牆外，還要特別注意導流牆及曝氣器支撐橋之結構設計"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":187,"question":"上流式厭氧污泥床法處理有機廢水之COD有機負荷為","options":["30-50","20-40","10-30","1-10 kg COD/m³. day."],"answer":3,"category":"厭氧生物處理"},{"id":188,"question":"以柱塞流反應器活性污泥系統進行生物除氮時，在何位置進行脫硝反應較為適當?","options":["曝氣槽","無氧接觸槽","沉澱池","污泥區"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":189,"question":"微生物生長所需氮源來自","options":["大氣的氮","無機氮化物","蛋白質或其他有機氮化物","以上皆是"],"answer":4,"category":"微生物與生物處理基礎"},{"id":190,"question":"生物去氮操作下列何者描述為誤?","options":["氨氮可由亞硝酸菌氧化為亞硝酸鹽","完全去氮為好氧生物處理程序","亞硝酸鹽經硝酸菌氧化反應為硝酸鹽","脫硝菌之作用，還原成氮氣而逸散於空氣中"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":191,"question":"好氧與厭氧處理程序比較，以下敘述何者有誤?","options":["能源損耗以好氧較高","生成物以厭氧較多","營養需求以好氧需求較大","好氧可單獨或串聯使用"],"answer":2,"category":"厭氧生物處理"},{"id":192,"question":"下列有關支流式及浸入式MBR特性比較之敘述，何者錯誤?","options":["支流式MBR之通量較低","支流式MBR在積垢控制上較容易","支流式MBR在能源消耗上較高","支流式MBR在操作彈性上較良好"],"answer":1,"category":"MBR 薄膜生物反應器"},{"id":193,"question":"以下針對懸浮與附著生長式生物處理系統敘述何者有誤?","options":["懸浮生長式對進流水中毒性物質相當敏感","懸浮生長式微生物基質利用率較不受質量傳輸的限制","附著生長式若適當組合可發揮去磷與脫硝功能","附著生長式污泥產生量較少"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":194,"question":"微生物篩選槽槽體大小須具備足夠停留時間讓回流污泥膠羽快速攝取溶解性有機物，以利後續處理程序，一般水力以不超過幾分鐘為原則","options":["30","60","90","120"],"answer":2,"category":"活性污泥與操作控制"},{"id":195,"question":"污泥處理單元前處理添加藥劑主要目的為","options":["促進污泥粗粒化","增大凝聚力","提高過濾效率","以上皆是"],"answer":4,"category":"污泥處理與處置"},{"id":196,"question":"自營性細菌可自氧化無機物而獲得能量，以下何種微生物不屬於自營性細菌?","options":["藻類","硝化菌","氫細菌","硫氧化菌"],"answer":1,"category":"微生物與生物處理基礎"},{"id":197,"question":"量測污泥容積指標(SVI)時，混合懸浮液應靜置多久?","options":["5","15","30","60分鐘"],"answer":3,"category":"活性污泥與操作控制"},{"id":198,"question":"針對傳統廢污水處理單元程序之組合順序，下列何者正確? A.曝氣槽 B.沉砂池 C.攔污柵 D.初沉池 E.終沉池 F.調整池 G.消毒池","options":["F-B-C-D-A-E-G","C-F-D-B-A-E-G","F-C-B-A-D-E-G","C-B-F-D-A-E-G"],"answer":4,"category":"活性污泥與操作控制"},{"id":199,"question":"以下何者經常與真空過濾合併使用，是目前最常見的脫水處理方法?","options":["離心式","壓力過濾式","水平帶式","真空過濾式"],"answer":3,"category":"污泥處理與處置"},{"id":200,"question":"污泥乾燥主要目的在","options":["蒸發水氣","降低水分含量","以利焚化或製成肥料","以上皆是"],"answer":4,"category":"污泥處理與處置"},{"id":201,"question":"以下何者是二級處理利用微生物去除的物質?","options":["溶解性有機化合物","部分氮磷化合物","以上皆是","以上皆非"],"answer":3,"category":"微生物與生物處理基礎"},{"id":202,"question":"污泥厭氧消化必須注意主要影響效率之因子，以下敘述何者有誤?","options":["消化槽的深度","良好的攪拌","維持足夠長的污泥停留時間SRT","最佳的環境條件"],"answer":1,"category":"厭氧生物處理"},{"id":203,"question":"一般生物處理法係利用何種菌分解有機物?","options":["自營性菌","光自營性菌","化學自營性菌","異營性菌"],"answer":4,"category":"微生物與生物處理基礎"},{"id":204,"question":"酸形成菌在厭氧分解中之主要功能乃是將有機物轉化成何物，以下何者有誤?","options":["有機酸","甲烷","二氧化碳","氨"],"answer":4,"category":"厭氧生物處理"},{"id":205,"question":"下列何者非生物處理之重要環境因子","options":["溫度","懸浮固體","溶氧","pH"],"answer":2,"category":"微生物與生物處理基礎"},{"id":206,"question":"厭氧生物處理相較於好氧生物處理的差異下列何者正確?","options":["COD、BOD值較高受溫度影響低，剩餘污泥量高","COD、BOD值較低","受溫度影響低","剩餘污泥量高"],"answer":1,"category":"厭氧生物處理"},{"id":207,"question":"下列何者非為厭氧菌代謝最終產物","options":["CH4","H2S","H2O","S"],"answer":4,"category":"厭氧生物處理"},{"id":208,"question":"何者不是影響厭氧系統之化學因子?","options":["揮發酸","鹼度","pH","溫度"],"answer":4,"category":"厭氧生物處理"},{"id":209,"question":"一廢水廠平均進流水量為2，000m³/day，進流水曝氣槽廢水平均BOD為300mg/L，處理水平均BOD為20mg/L，活性污泥曝氣槽有效容積為600m³，曝氣槽污泥濃度MLSS=2，500mg/L，MLVSS/MLSS=0.8，則有機負荷(F/M)為何?","options":["0.5","1.0","100","1，000 kg BOD/kg MLVSS. day"],"answer":1,"category":"活性污泥與操作控制"},{"id":210,"question":"以下何者不是生物處理程序主要去除的物質?","options":["水溶性有機物","部分非水溶性有機物","無機離子","部分氮及磷"],"answer":3,"category":"微生物與生物處理基礎"},{"id":211,"question":"以下何種不屬於附著生長式?","options":["滴濾池法","生物圓盤法","批式活性污泥法","接觸曝氣法"],"answer":3,"category":"附著生長與生物膜"},{"id":212,"question":"懸浮生長之生物處理方法具有","options":["對進流水中毒性物質較能忍受","基質利用率受質傳影響","有時可不用二級沉澱池","二級沉澱池的操作影響反應爐內污泥濃度"],"answer":4,"category":"微生物與生物處理基礎"},{"id":213,"question":"選出屬於附著生長式生物處理方法之特性","options":["反應爐中不加入介質","對廢水中毒性物質較能忍受","微生物利用基質不受質傳的限制","二級沉澱池的操作影響反應爐內污泥的濃度"],"answer":2,"category":"附著生長與生物膜"},{"id":214,"question":"厭氧濾床法之污泥微生物生長係數(Y值)小，可減少污泥處理費用，其值為?","options":["0.3-0.1","0.05-0.1","0.02-0.05","0.01以下"],"answer":4,"category":"附著生長與生物膜"},{"id":215,"question":"選出屬於好氧生物分解之特性","options":["污泥產生量低","生成物能量高","合成作用快","主要最終產物為甲烷"],"answer":3,"category":"微生物與生物處理基礎"},{"id":216,"question":"標準活性污泥法曝氣槽內污泥中細菌，其生長階段係在","options":["對數增殖期","介於對數增殖期與減率增殖期","減率增殖期","介於減率增殖期與體內呼吸期"],"answer":4,"category":"活性污泥與操作控制"},{"id":217,"question":"活性污泥變黑，以下解決對策何者有誤?","options":["降低進流量","提高進水pH值","增加曝氣","加大迴流污泥量"],"answer":2,"category":"活性污泥與操作控制"},{"id":218,"question":"標準活性污泥法與SBR之差異何者有誤","options":["前者污泥無須迴流，後者在處理槽及沉澱池中迴流","前者為連續排水，後者週期排水","前者為有機負荷均一，後者週期變化","前者為連續曝氣，後者間歇式曝氣"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":219,"question":"廢水處理中，譬如pH值為7時，氮濃度一般不可大於","options":["1，000","1，600","3，000","2，500 mg/L"],"answer":2,"category":"微生物與生物處理基礎"},{"id":220,"question":"廢水生物處理方法普遍採用中溫細菌作為有機物分解的微生物，其最佳生長溫度為?","options":["10-25℃","20-30℃","25-37℃","35~45℃"],"answer":3,"category":"微生物與生物處理基礎"},{"id":221,"question":"廢水中BOD的生物去除作用，主要來自於","options":["分解作用","合成作用","分解作用及合成作用","光合作用"],"answer":3,"category":"微生物與生物處理基礎"},{"id":222,"question":"滴濾池中之微生物，主要以細菌佔優勢，而細菌中含有","options":["好氧菌","厭氧菌","好氧菌及厭氧菌","好氧菌、厭氧菌及兼氧菌"],"answer":4,"category":"附著生長與生物膜"},{"id":223,"question":"在水體中的含氮污染物主要以有機氮及無機氮兩種形式存在，以下何者不屬於有機氮","options":["氨氮","蛋白質","胺基酸","尿素"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":224,"question":"一般生活污水處理廠，進行污泥處理之主要目的為減少?","options":["農藥及油脂","水分及有機物含量","重金屬及無機物","以上皆非"],"answer":2,"category":"微生物與生物處理基礎"},{"id":225,"question":"下列有關好氧(與)厭氧處理程序比較之敘述，何者正確?","options":["前者能源耗用高，且產生較多污泥量","前者能源耗用低，且產生較多污泥量","後者能源耗用高","後者產生較多污泥量"],"answer":1,"category":"厭氧生物處理"},{"id":226,"question":"氧化渠法較接近活性污泥法中的哪一類型?","options":["延長曝氣法","階梯曝氣法","接觸曝氣法","漸減曝氣法"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":227,"question":"下列生物處理方法中較不會有污泥阻塞問題之方法為","options":["接觸曝氣法","厭氧接觸法","厭氧濾床法","滴濾池法"],"answer":2,"category":"厭氧生物處理"},{"id":228,"question":"下列生物處理方法中污泥濃度最高的方法為?","options":["活性污泥法","氧化渠法","批式活性污泥法","厭氧污泥床法"],"answer":4,"category":"厭氧生物處理"},{"id":229,"question":"下列有關生物除磷特性之敘述，何者有誤?","options":["活性污泥僅能攝取少量磷酸鹽","欲提高除磷率，使生物污泥在缺氧情況下釋磷，再用石灰將磷酸鹽轉化為磷酸鈣沉除","釋磷後生物污泥之攝磷率提高，廢棄污泥含較低濃度之磷","廢水中磷多以磷酸鹽及多磷酸鹽存在"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":230,"question":"一廢水廠平均進流水量為2，000m³/day，進流水曝氣槽廢水平均BOD為300mg/L，處理水平均BOD為20mg/L，活性污泥曝氣槽有效容積為600m³，則容積負荷(F/V)為何?","options":["3.3","1.0","100","1，000 kg BOD/m³"],"answer":2,"category":"活性污泥與操作控制"},{"id":231,"question":"下列何種化合物不可作為厭氧生物處理系統之電子最後接受者?","options":["H2S","NO3-","SO42-","HCO3-"],"answer":1,"category":"厭氧生物處理"},{"id":232,"question":"下列何種活性污泥法流程，其需氧速率隨曝氣池長度成上下震盪變化?","options":["傳統式活性污泥法","接觸穩定法","階梯曝氣法","延長曝氣法"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":233,"question":"下列厭氧生物處理方法中，處理廢水有機負荷量最大者為","options":["厭氧接觸法","厭氧濾床法","上流式厭氧污泥床法","厭氧流體化床法"],"answer":4,"category":"附著生長與生物膜"},{"id":234,"question":"污泥容積指標(SVI)常作為量測污泥何種性質之指標?","options":["污泥黏滯程度","生物可分解性","沉降性","消化污泥中總固體物減少率"],"answer":3,"category":"活性污泥與操作控制"},{"id":235,"question":"接觸曝氣法反沖洗時一般設計之容積負荷為","options":["0.1-0.4","0.4-0.5","0.5-1.0","0.8-1.5 kg BOD5/m³. day"],"answer":2,"category":"附著生長與生物膜"},{"id":236,"question":"生物處理方法之廢棄污泥處理過程，可免設污泥消化設備之生物處理方法為","options":["傳統活性污泥法","生物圓盤法","氧化渠法","批式活性污泥法"],"answer":3,"category":"污泥處理與處置"},{"id":237,"question":"生物處理若依有無供給氧氣情況加以分類，不包括下列何種程序?","options":["好氧性處理","兼氧性處理","厭氧性處理","懸浮生長式"],"answer":4,"category":"微生物與生物處理基礎"},{"id":238,"question":"在污泥厭氧消化時，如系統不正常，則可能造成?","options":["有機物負荷或流量負荷之突變","揮發酸濃度逐漸累積","pH、氣體產量、CH4比例及有機物減少率降低","以上皆是"],"answer":4,"category":"厭氧生物處理"},{"id":239,"question":"污泥乾燥床用來乾燥消化污泥時，若置放之污泥厚度一般約為?","options":["5~10","20~30","50-70","90~110公分"],"answer":2,"category":"污泥處理與處置"},{"id":240,"question":"自營性細菌可自氧化無機物而獲得能量，下列細菌何者不屬於自營性細菌?","options":["甲烷菌","硫氧化菌","硝化菌","鐵氧化菌"],"answer":1,"category":"厭氧生物處理"},{"id":241,"question":"以操作經驗顯示，以藻類與真菌為主的系統，其較佳生長過程之pH值為何?","options":["3.0","6.0","7.0","9.0"],"answer":2,"category":"微生物與生物處理基礎"},{"id":242,"question":"活性污泥在正常操作狀態時，可藉下列何種微生物的出現，作為判定出流水水質是否清澈(即處理功能良好)之一項重要生物指標","options":["輪蟲","細菌","根足蟲","鞭毛蟲"],"answer":1,"category":"活性污泥與操作控制"},{"id":243,"question":"活性污泥膜濾法(MBR)主要為利用超過濾UF或微過濾MF 薄膜由活性污泥系統中分離生物污泥，以取代下列何種傳統之活性污泥處理單元?","options":["曝氣槽","沉澱池","迴流污泥設備","滴濾池"],"answer":2,"category":"MBR 薄膜生物反應器"},{"id":244,"question":"為減少突增及洪峰濃度，及調勻進流廢水之水量與水質變化，活性污泥法曝氣槽之設計以","options":["柱塞流型反應槽","完全混合型反應槽","介於柱塞流及完全混合型反應槽","生物膜反應槽為宜"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":245,"question":"為維持曝氣槽內之污泥濃度，標準活性污泥法曝氣槽內較適當之MLSS值範圍為何?","options":["150-400","500-800","1，500-3，000","5，000-6，000 mg/L"],"answer":3,"category":"活性污泥與操作控制"},{"id":246,"question":"氧化深渠適宜處理之有機負荷為___kg BOD5/kg MLSS. day","options":["0.05-0.15","0.15-0.3","0.2-0.5","0.5-0.8"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":247,"question":"若迴流污泥(XR)約等於曝氣槽中之MLSS，則污泥可能在最終沉澱池產生下列何種現象?","options":["膨化","解體","污泥上升","以上皆是"],"answer":4,"category":"活性污泥與操作控制"},{"id":248,"question":"下列有關氧化渠之特性敘述，何者錯誤?","options":["所需處理用地較小","不需設置初沉池","處理操作簡單","操作時臭味產生較少"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":249,"question":"下列病毒特性之敘述，何者正確?","options":["可自我複製","能感染細菌或動植物細胞","病毒體對寄主不具有特定性","病毒構造複雜，大多由核酸及蛋白質外殼組成"],"answer":2,"category":"微生物與生物處理基礎"},{"id":250,"question":"下列有關接觸曝氣法之特性敘述，何者有誤?","options":["接觸槽比表面積較大","污泥產生量少","較易調節所附著之生物膜量","具有較高的緩衝能力"],"answer":3,"category":"附著生長與生物膜"},{"id":251,"question":"下列有關接觸曝氣法之接觸材料特性敘述，何者有誤?","options":["生物膜容易附著","比表面積大","孔隙率小","與水之比重相近"],"answer":3,"category":"附著生長與生物膜"},{"id":252,"question":"下列有關厭氧流體化床反應器(AFBR)特性之敘述，何者有誤?","options":["活性生物濃度高，可縮短生物反應時間","生物膜生長速率快，啟動時間短","操作管理需要較高的技術","減少反應槽體積及用地面積"],"answer":2,"category":"附著生長與生物膜"},{"id":253,"question":"下列有關厭氧濾床法特性之敘述，何者有誤?","options":["不易阻塞","污泥消化完全，減少污泥處理費用","水力停留時間(HRT)可以縮短","不需污泥迴流即能得到很長的污泥停留時間(SRT)"],"answer":1,"category":"附著生長與生物膜"},{"id":254,"question":"下列有關活性污泥膜濾法(MBR)之特性敘述，何者有誤?","options":["污泥可完全截留","可去除細菌和病毒","污泥濃度高","污泥停留時間短"],"answer":4,"category":"MBR 薄膜生物反應器"},{"id":255,"question":"下列有關活性污泥膜濾法(MBR)與傳統活性污泥(AS)程序之特性比較，何者有誤?","options":["AS之能源使用較高","AS之反應速率慢","AS處理水水質較不穩定","AS所產生之污泥量較多"],"answer":1,"category":"MBR 薄膜生物反應器"},{"id":256,"question":"下列有關活性污泥膜濾法(MBR)與傳統活性污泥(AS)程序之特性比較，何者正確?","options":["MBR之佔地面積較大","MBR之污泥產量較少","AS反應速率快","AS之處理水質較為穩定"],"answer":2,"category":"MBR 薄膜生物反應器"},{"id":257,"question":"下列對於批式活性污泥法之操作及處理何者有誤","options":["週期進水","週期排水","間歇式曝氣","需要污泥迴流"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":258,"question":"下列何者為水中有機物好氧性生物處理之產物?","options":["硫化氫","硝酸鹽","氨","甲烷"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":259,"question":"未處理初級污泥具有下列何種物質，故具有肥料特性?","options":["氮","磷","鉀","以上皆是"],"answer":4,"category":"微生物與生物處理基礎"},{"id":260,"question":"以污泥泵輸送污泥時，在管線內之流速之適宜範圍?","options":["0.3-0.6","1.0-2.4","4.3-5.6","6.6-8.0m/s"],"answer":2,"category":"微生物與生物處理基礎"},{"id":261,"question":"下列有關活性污泥法之操作參數敘述，何者有誤?","options":["食微比(F/M)為每日流入曝氣槽內的有機物質量與曝氣槽內污泥質量的比值","污泥齡係微生物(污泥)在活性污泥系統中之平均停留時間","SVI為1公升混合懸浮液靜置30分鐘，所量得之污泥量容積","污泥迴流比為迴流污泥量與流入廢水量之比率"],"answer":3,"category":"活性污泥與操作控制"},{"id":262,"question":"以有機化合物作為能源及碳源的微生物稱為","options":["化學異營性菌","化學自營性菌","光合異營性菌","光合自營性菌"],"answer":1,"category":"微生物與生物處理基礎"},{"id":263,"question":"水中有機物之厭氧穩定化過程，下列何者正確?","options":["酸化→酸化","甲烷化→甲烷化","酸化→甲烷化","甲烷化→酸化"],"answer":3,"category":"厭氧生物處理"},{"id":264,"question":"介於懸浮生長式與附著生長式之間的生物處理方法為","options":["活性污泥法","氧化渠","滴濾法","流體化床法"],"answer":4,"category":"附著生長與生物膜"},{"id":265,"question":"以下何者不是影響硝化反應之因子","options":["抑制性物質","BOD/TKN比值","基質濃度","顆粒大小"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":266,"question":"接觸穩定法有接觸槽、穩定槽及沉澱槽，處理過程中真正進行生物分解反應的槽體為","options":["接觸槽","穩定槽","接觸槽及穩定槽","所有三個槽體"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":267,"question":"理論上1mg硝酸鹽脫硝反應會產生","options":["3.57","2.6","4.6","5.6 mg CaCO3鹼度"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":268,"question":"下列何者不為SBR具有之處理功能?","options":["硝化","脫硝","脫磷","脫硫"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":269,"question":"影響浮除濃縮加壓水量之主要因素為?","options":["壓力槽壓力","氣固比","水溫","以上皆是"],"answer":4,"category":"微生物與生物處理基礎"},{"id":270,"question":"生物處理系統一般最佳pH範圍介於?","options":["6.5~7.5間","3.5-4.5之間","8.0-9.0之間","以上皆是"],"answer":1,"category":"微生物與生物處理基礎"},{"id":271,"question":"廢水中微生物與有機物的作用，主要為","options":["分解作用","合成作用","分解作用及合成作用","光合作用"],"answer":3,"category":"微生物與生物處理基礎"},{"id":272,"question":"厭氧消化槽開始不正常時，常出現揮發酸與鹼度之比值?","options":["升高","降低","不變","以上皆是"],"answer":1,"category":"厭氧生物處理"},{"id":273,"question":"厭氧消化過程中，通常每去除1公斤COD在標準狀態下可產生","options":["0.25","0.35","0.45","0.55 Nm³之甲烷"],"answer":2,"category":"厭氧生物處理"},{"id":274,"question":"厭氧消化之主要氣體產物之一為?","options":["氮氣","甲烷","氧氣","以上皆非"],"answer":2,"category":"厭氧生物處理"},{"id":275,"question":"下列生物處理方法何者不屬於生物膜法?","options":["滴濾法","生物圓盤法","厭氧濾池法","厭氧接觸法"],"answer":4,"category":"附著生長與生物膜"},{"id":276,"question":"下列何者不屬於生物厭氧分解的特性","options":["合成作用慢","生成物能量高","污泥產生量高","主要最終產物為CH4"],"answer":3,"category":"厭氧生物處理"},{"id":277,"question":"活性污泥系統的必要條件為","options":["好氧性微生物","基質(有機物)和充足的溶氧","迴流污泥","以上皆是"],"answer":4,"category":"活性污泥與操作控制"},{"id":278,"question":"下列何者為標準活性污泥法曝氣槽中，溶氧濃度(mg/L)應保持的範圍?","options":["0.5~1","1~3","3~5","5~7mg/L"],"answer":2,"category":"活性污泥與操作控制"},{"id":279,"question":"活性污泥中的真菌屬於","options":["化學異營性菌","化學自營性菌","光合自營性菌","光合異營性菌"],"answer":1,"category":"活性污泥與操作控制"},{"id":280,"question":"生物處理方法中屬於懸浮生長式之方法為?","options":["厭氧接觸法","生物圓盤法","接觸曝氣法","厭氧濾床法"],"answer":1,"category":"厭氧生物處理"},{"id":281,"question":"以無機化合物之氧化作用作為能量來源，二氧化碳作為碳源的微生物稱為","options":["化學異營性菌","化學自營性菌","光合異營性菌","光合自營性菌"],"answer":2,"category":"微生物與生物處理基礎"},{"id":282,"question":"下列何種為接觸曝氣系統之反沖洗時機?","options":["曝氣槽內接觸材上之水位上升","曝氣槽內SS之濃度增加","曝氣槽內有黑色厭氧臭味之SS出現","以上皆是"],"answer":4,"category":"附著生長與生物膜"},{"id":283,"question":"下列有關氧化渠特性之敘述，何者錯誤?","options":["具有較大的緩衝容量，受水質水量負荷之影響較小","處理操作簡單，曝氣設施之清理維護簡易，所需人力少","廢棄污泥量較少並可免設污泥消化設備，直接曬乾","所需處理用地較小"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":284,"question":"廢水之缺氧性處理之反應過程為[有機物+硝酸根離子+微生物→增殖生物+二氧化碳+水+?]應該是何物?","options":["氮","氧","氧化劑","混凝劑"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":285,"question":"好氧生物處理程序，每去除1公斤COD約可產生多少公斤的污泥?","options":["0.01~0.1","0.2-0.5","0.5-0.8","1.0"],"answer":2,"category":"微生物與生物處理基礎"},{"id":286,"question":"哪一個階段係在食微比較大時發生，且微生物去除有機物量較多，但污泥欠缺凝聚性及沉降性","options":["遲滯期","對數增殖期","減率增殖期","體內呼吸期"],"answer":2,"category":"活性污泥與操作控制"},{"id":287,"question":"活性污泥處理發現曝氣池有白色泡沫過多時，以下可能原因及解決對策何者正確?","options":["進水負荷高，F/M大於0.5","降低進水pH值","曝氣池供氧不足","絲狀菌或固著型纖毛蟲大量繁殖"],"answer":4,"category":"活性污泥與操作控制"},{"id":288,"question":"污泥去除有機物之主要機構為何，以下何者有誤?","options":["脫落","吸著","氧化","同化"],"answer":1,"category":"微生物與生物處理基礎"},{"id":289,"question":"以下何者不是影響SBR操作之環境因子","options":["溶氧值","重金屬","pH值","溫度"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":290,"question":"下列有關橫流過濾方式MBR之敘述，何者錯誤?","options":["懸浮液流動方向與薄膜表面垂直","懸浮液在薄膜表面之橫流產生剪力作用而避免形成過厚濾餅","當濾餅之累積與重效應達到平衡，濾餅厚度即固定","可避免濾餅積垢產生以得最大滲透通量"],"answer":1,"category":"MBR 薄膜生物反應器"},{"id":291,"question":"有關薄膜端點過濾與橫流過濾，下列何者不正確?","options":["端點過濾之泥餅較厚","端點過濾之通量降低較大","橫流過濾之濾餅阻力較大","橫流過濾之通量降低較小"],"answer":3,"category":"微生物與生物處理基礎"},{"id":292,"question":"下列有關端點過濾方式MBR之敘述，何者有誤?","options":["懸浮液流動方向與薄膜表面平行","固體物被截留在薄膜表面形成濾餅層","濾餅厚度隨過濾量增加而增加","滲透液流量隨濾餅厚度增加而減少"],"answer":1,"category":"MBR 薄膜生物反應器"},{"id":293,"question":"下列有關支流式及浸入式MBR特性比較之敘述，何者錯誤?","options":["浸入式MBR之通量較低","支流式MBR在積垢控制上較容易","浸入式MBR在改裝方便性上較容易","支流式MBR在操作彈性上較良好"],"answer":3,"category":"MBR 薄膜生物反應器"},{"id":294,"question":"硝化作用有機負荷BOD/TKN的高低，將直接影響活性污泥系統中硝化菌之比例，一般控制BOD/TKN在3以下，硝化菌之比例?","options":["增加","減少","不變","以上皆是"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":295,"question":"下列厭氧生物處理方法之反應槽，何者容易產生較高之水頭損失?","options":["厭氧接觸系統","厭氣污泥床","厭氧流體化床","厭氧濾床"],"answer":3,"category":"附著生長與生物膜"},{"id":296,"question":"好氧消化槽操作的注意事項中，下列何者為非?","options":["溶氧應不低於3mg/L","停留時間，生物污泥應為10-15天，混合污泥應15-20天","pH值應高於6.5","依照上澄液之水質選擇對應水深度，抽取上澄液時，應暫停循環混合"],"answer":1,"category":"活性污泥與操作控制"},{"id":297,"question":"好氧消化池之水力停留時間(day)應在那一範圍內?","options":["1-2","5~10","15-20","25-30"],"answer":3,"category":"微生物與生物處理基礎"},{"id":298,"question":"下列柱塞流型傳統活性污泥法與階梯曝氣法處理有機廢水之異同點比較中，選出不正確的陳述?","options":["迴流污泥由曝氣槽前端進入","兩種方法廢水進流曝氣槽之點位不同","均為長渠形水路之曝氣槽","去除一定BOD量所需曝氣槽容積相同"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":299,"question":"生物去氮除磷處理流程為何?","options":["厭氧、缺氧及好氧生物處理流程","厭氧、厭氧及好氧生物處理流程","好氧、缺氧及好氧生物處理流程","缺氧、缺氧及好氧生物處理流程"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":300,"question":"針對生物脫硝作用之敘述，何者有誤?","options":["由自營性脫硝菌促成","需額外有機碳源參與反應","適當pH範圍為6.5-7.5","可在如活性污泥之懸浮性生物反應器中進行"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":301,"question":"上流式厭氧污泥床(UASB)反應槽分成4個主要部分，其主要反應區域為下列何者?","options":["污泥層","污泥床","沉降區","氣固液三相分離器"],"answer":2,"category":"厭氧生物處理"},{"id":302,"question":"污泥容積指數SVI 用於判斷活性污泥的?","options":["吸附性能","增殖性能","沉降性能","絮凝性能"],"answer":3,"category":"活性污泥與操作控制"},{"id":303,"question":"污泥去除有機物之主要機構，其進行順序何者正確","options":["氧化→吸著→同化","吸著→氧化→同化","同化→氧化→吸著","吸著→同化→氧化"],"answer":2,"category":"微生物與生物處理基礎"},{"id":304,"question":"中心曝氣方式的矩形接觸曝氣槽，其水深與槽寬的比值，下列何者正確?","options":["1:1.5以下","1:2.5以下","1:3.5以下","1:4.5以下"],"answer":2,"category":"附著生長與生物膜"},{"id":305,"question":"以下何種重金屬之金屬離子毒性強度最強","options":["Ag","Zn","Cd","Sn"],"answer":1,"category":"微生物與生物處理基礎"},{"id":306,"question":"傳統活性污泥法之F/M有機負荷約為多少(kg BOD5)/(kg MLVSS. day)?","options":["0.02~0.05","0.2~0.5","0.5~0.75","2~5"],"answer":2,"category":"活性污泥與操作控制"},{"id":307,"question":"下列何者為污泥容積指標(SVI)之單位?","options":["mg/L","g/mL","mL/g","L/mg."],"answer":3,"category":"活性污泥與操作控制"},{"id":308,"question":"主要原理係利用培養之粒狀生物污泥，靠其本身重力沉降作用及反應槽上方的沉降裝置，使生物在反應槽下形成高濃度的污泥床，達到處理含固形物少而溶解性有機質高的工業廢水之目的為何種廢水處理法","options":["厭氧接觸法","上流式厭氧污泥床法","厭氧濾床法","厭氧流體化床法"],"answer":2,"category":"厭氧生物處理"},{"id":309,"question":"一個懸浮固體濃度為3，000mg/L之混合液取樣1，000mL，經30分鐘沉降後，污泥體積為150mL","options":["SVI=50 mL/g","SVI=80 mL/g","SVI=100 mL/g","SVI=120 mL/g."],"answer":1,"category":"活性污泥與操作控制"},{"id":310,"question":"有關生物去氮除磷處理流程，下列敘述何者有誤?","options":["利用厭氧、缺氧及好氧生物處理的流程","藉由厭氧好氧處理程序去除廢水中含磷物質","藉由好氧缺氧處理程序，去除廢水中含氮物質","以上皆對"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":311,"question":"一懸浮固體量為1，500mg/L之混合液取樣1，000mL，經30分鐘沉降後，污泥體積為180mL，試計算該混合液之SVI","options":["SVI=50 mL/g","SVI=80 mL/g","SVI=100 mL/g","SVI=120 mL/g."],"answer":4,"category":"活性污泥與操作控制"},{"id":312,"question":"通常SVI在多少mL/g以上，將表示活性污泥嚴重膨化","options":["100","200","300","400"],"answer":2,"category":"活性污泥與操作控制"},{"id":313,"question":"針對生物脫硝作用之敘述，何者有誤?","options":["硝化反應僅能轉化氨氮為硝酸態氮，並無法完全去除廢水中總氮","欲有效去除總氮，尚須借助脫硝反應","脫硝反應是指脫硝菌將硝酸鹽氮氧化成氮氣的過程","脫硝反應為一種在無氧狀態下之反應"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":314,"question":"下列何者生物處理程序可進行硝化","options":["活性污泥法","厭氧污泥床","厭氧消化槽","厭氧接觸系統"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":315,"question":"廢水使用生物處理主要是針對","options":["非溶解性有機物","高濃度無機物","固體性有機物","溶解性有機物及部分氮磷"],"answer":4,"category":"微生物與生物處理基礎"},{"id":316,"question":"廢水之厭氧性生物處理產物不包括","options":["CO2","CH4","NO3-","H2S"],"answer":3,"category":"厭氧生物處理"},{"id":317,"question":"廢水之缺氧性生物處理主要為何物質存在","options":["CO2","CH4","NO3-","H2S."],"answer":3,"category":"微生物與生物處理基礎"},{"id":318,"question":"廢水之好氧性生物處理產物不包括","options":["CO2","CH4","NO3-","H2S."],"answer":2,"category":"微生物與生物處理基礎"},{"id":319,"question":"附著性生物處理程序不包括","options":["活性污泥法","接觸曝氣法","生物圓盤法","滴濾池法"],"answer":1,"category":"活性污泥與操作控制"},{"id":320,"question":"附著性生物法較懸浮性之差異何者正確","options":["質傳較好","毒性容忍高","污泥產生多","營養需求多"],"answer":2,"category":"微生物與生物處理基礎"},{"id":321,"question":"在好氧性處理中，廢水之有機物被好氧性微生物分解，下列何者非屬好氧反應過程之最終產物?","options":["硝酸鹽(NO3-)","二氧化碳(CO2)","水(H2O)","硫化氫(H2S)"],"answer":4,"category":"微生物與生物處理基礎"},{"id":322,"question":"在厭氧性處理中，廢水之有機物被厭氧性微生物分解，下列何者非屬厭氧反應過程之最終產物?","options":["二氧化碳(CO2)","氨(NH3)","硫酸鹽(SO42-)","甲烷(CH4)"],"answer":3,"category":"厭氧生物處理"},{"id":323,"question":"下列有關生物處理環境因子之敘述，何者有誤","options":["各種細菌在最佳生長溫度範圍之外，其生長速率將受到抑制而降低","pH的變化主要影響酵素的活性度，使微生物的生長過程受到影響","重金屬對生物的毒害程度不受水中共存物質的影響","高濃度的鹽分將影響微生物的活性度，會降低生物處理效果"],"answer":3,"category":"微生物與生物處理基礎"},{"id":324,"question":"化合性微生物之性質中，包含","options":["利用太陽能","依賴化合物為能量來源","從光獲得能源","以上皆非"],"answer":2,"category":"微生物與生物處理基礎"},{"id":325,"question":"光合性菌和化學菌是以下列何者為分類","options":["能源","碳源","磷源","氮源"],"answer":1,"category":"微生物與生物處理基礎"},{"id":326,"question":"自營性菌和異營性菌係根據生長需要下列何者而區分?","options":["碳源","氮源","硫、磷源","維生素"],"answer":1,"category":"微生物與生物處理基礎"},{"id":327,"question":"藻類的能量來源及最基本之生理特性是?","options":["光合作用","分裂生殖","好氧性","厭氧性"],"answer":1,"category":"微生物與生物處理基礎"},{"id":328,"question":"何者不是生物處理系統中常用於處理有機物的微生物?","options":["細菌","藻類","真菌","原生動物"],"answer":2,"category":"微生物與生物處理基礎"},{"id":329,"question":"一般廢水處理生物系統微生物屬於","options":["低溫菌","中溫菌","高溫菌","超高溫菌"],"answer":2,"category":"微生物與生物處理基礎"},{"id":330,"question":"一般好氧系統氯化物濃度不可大於多少mg/L?","options":["50","500","5，000","50，000"],"answer":3,"category":"微生物與生物處理基礎"},{"id":331,"question":"活性污泥法在正常操作狀態時，可藉由下列何種微生物的出現作為判定處理功能良好的指標","options":["細菌","原生動物","真菌","藻類"],"answer":2,"category":"活性污泥與操作控制"},{"id":332,"question":"活性污泥代謝營養分，若BOD5濃度為200mg/L，請問N的需求為","options":["5","10","15","20 mg/L"],"answer":2,"category":"活性污泥與操作控制"},{"id":333,"question":"活性污泥曝氣槽操作何者正確?","options":["MLSS於1，500~3，000mg/L","溶氧1~3mg/L","pH 6.5~7.5","以上皆是"],"answer":4,"category":"活性污泥與操作控制"},{"id":334,"question":"活性污泥系統中，迴流污泥之目的是","options":["減少污泥產生量","維持曝氣槽之微生物濃度","維持污泥的排放量","以上皆非"],"answer":2,"category":"活性污泥與操作控制"},{"id":335,"question":"處理廠操作人員控制活性污泥系統最主要的操作要素為","options":["迴流污泥","曝氣量","污泥濃度","進流水濃度"],"answer":1,"category":"活性污泥與操作控制"},{"id":336,"question":"曝氣槽多為矩形槽槽寬與深比為","options":["0.5","1.0","1.0~1.5","3.0以上"],"answer":3,"category":"活性污泥與操作控制"},{"id":337,"question":"污泥膨化可能的因素有","options":["廢水特性","設計限制","操作問題","以上皆是"],"answer":4,"category":"微生物與生物處理基礎"},{"id":338,"question":"污泥膨化處理何者有誤","options":["設篩選槽","加氯","二沉池加混凝劑","降低pH"],"answer":4,"category":"微生物與生物處理基礎"},{"id":339,"question":"有關污泥容積指標之敘述何者有誤","options":["量測時是以30分鐘的污泥量之容積為計算基準","是針對MLSS而言","SVI太大表示污泥沉降性及濃縮性不佳","當F/M過高及有特殊有毒工業廢水流入時，常使SVI值降低"],"answer":4,"category":"活性污泥與操作控制"},{"id":340,"question":"延長曝氣法之生物處理系統，主要是利用微生物增殖過程之特性是?","options":["對數增殖期的少量污泥濃度","減率增殖期的較多量污泥濃度","增率增殖期的較多BOD量","體內呼吸期的較少量污泥濃度"],"answer":4,"category":"SBR／氧化渠與改良活性污泥法"},{"id":341,"question":"活性污泥膜濾法(MBR)是利用薄膜取代傳統活性污泥法的何種設備?","options":["柵欄","沉澱池與砂濾池","曝氣槽","沉澱池與曝氣槽"],"answer":2,"category":"MBR 薄膜生物反應器"},{"id":342,"question":"支流式MBR之特色和浸入式比較何者有誤?","options":["較佔空間","透膜壓力較大","產生通量大","能量消耗較小"],"answer":4,"category":"MBR 薄膜生物反應器"},{"id":343,"question":"以下MBR特性敘述何者錯誤","options":["MBR之污泥濃度高可以處理高濃度變化廢水","MBR之污泥停留時間較長有利於難分解污染物的去除","MBR之F/M比較高污泥產生量較多","MBR可去除細菌和病毒以達到消毒作用"],"answer":3,"category":"MBR 薄膜生物反應器"},{"id":344,"question":"傳統活性污泥法與活性污泥膜濾系統比較，何者正確?","options":["前者會消耗較多能源","後者會產生大量污泥","前者污泥濃度高，反應速率快","後者污泥濃度高，反應速率快"],"answer":4,"category":"MBR 薄膜生物反應器"},{"id":345,"question":"有關接觸曝氣槽水深與池寬比敘述，何者正確?","options":["單側曝氣1:1.3以下","中心曝氣1:2.5以下","以上皆對","以上皆非"],"answer":3,"category":"附著生長與生物膜"},{"id":346,"question":"接觸曝氣法敘述何者正確?","options":["接觸材表面應避免附著生物膜","需要反沖洗過厚生物膜","屬於懸浮性生物處理法","本法需有完整的沉澱池"],"answer":2,"category":"附著生長與生物膜"},{"id":347,"question":"生物網膜技術敘述何者有誤","options":["簡稱BioNET","多孔性擔體作為反應槽之介質","提高懸浮固體物攔截","以上皆非"],"answer":4,"category":"微生物與生物處理基礎"},{"id":348,"question":"何者不屬於無機氮?","options":["胺基酸","氨氮","亞硝酸氮","硝酸氮"],"answer":1,"category":"微生物與生物處理基礎"},{"id":349,"question":"最適合硝化反應的溫度為","options":["低於15℃","20~25℃","30~35℃","40~45℃"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":350,"question":"硝化菌群屬自營性細菌其污泥齡須維持在","options":["小於5天","小於10天","15天左右","50天以上"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":351,"question":"當溶氧濃度高於多少時，脫硝作用即受到抑制","options":["0.2","0.5","1","2~3 mg/L."],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":352,"question":"對於同時進行有機物生物處理流程中，氨氮可被細菌氧化成亞硝酸鹽，再氧化成?","options":["有機氮","凱氏氮","亞硝酸鹽","硝酸鹽"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":353,"question":"有關生物除氮反應何者不正確?","options":["硝化為好氧反應","硝化反應受有機物濃度影響","脫硝反應不需有機物","脫硝為厭氧反應"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":354,"question":"生物處理流程中，氨氮可被細菌轉化成硝酸鹽，稱為何種反應?","options":["硝化","氮化","脫硝","氨化"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":355,"question":"一般含氮化合物生物去除程序，包括何種反應?","options":["有機氮水解","硝化","脫硝","以上皆對"],"answer":4,"category":"微生物與生物處理基礎"},{"id":356,"question":"生物除磷系統之主要除磷關鍵乃在透過促進系統中","options":["磷蓄積菌","磷氧化菌","磷脫附菌","磷攝取菌來降低廢水中之正磷酸鹽，再經由廢棄高含磷量污泥來達成除磷之目的"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":357,"question":"何種物質有利於磷蓄積菌於厭氧段時蓄積能量儲存物","options":["甲酸","甲醇","乙酸","乙醇，並形成含磷量較高的污泥"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":358,"question":"生物除磷程序中，好氧過程水體中磷的濃度是?","options":["下降","上升","不一定","不變"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":359,"question":"A2O處理程序所指為","options":["厭氧-好氧-缺氧","厭氧-缺氧-好氧","好氧-厭氧-缺氧","缺氧-厭氧-好氧"],"answer":2,"category":"厭氧生物處理"},{"id":360,"question":"脫硝菌適合生長之條件，以下敘述何者有誤","options":["pH範圍:6.5~7.5","DO濃度>0.2mg/L","MLVSS:1，200~2，500 mg/L","CH3OH/NO3>2.5"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":361,"question":"下列何者為活性污泥濃度(MLSS)之單位?","options":["mg/L","g/mL","mL/g","L/mg."],"answer":1,"category":"活性污泥與操作控制"},{"id":362,"question":"若污泥容積指標SVI太大，下列敘述何者正確?","options":["污泥沉降性及濃縮性不佳","污泥太過緊密","含太高比例之無機污泥","易造成排泥困難"],"answer":1,"category":"活性污泥與操作控制"},{"id":363,"question":"都市污水處理所產生之廢棄活性污泥其TS減少率為","options":["10~20%","20~50%","50~70%","70~90%"],"answer":2,"category":"活性污泥與操作控制"},{"id":364,"question":"上流式厭氧污泥床於反應槽上方的沉降裝置加裝傾斜板之用意在於?","options":["增加水力停留時間","增加粒子沉降速率","降低水流速度","增加SRT"],"answer":4,"category":"厭氧生物處理"},{"id":365,"question":"活性污泥處理發生污泥擴散顆粒破裂其異常狀況何者有誤?","options":["營養鹽不足","負荷過大","攪拌太激烈","有毒物質進入"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":366,"question":"活性污泥處理發生污泥成長慢其異常狀況何者有誤?","options":["營養鹽不足","負荷過大","酸化度過高","種泥不足"],"answer":2,"category":"活性污泥與操作控制"},{"id":367,"question":"一廢水廠平均進流水量為1，600m³/day，進流入曝氣槽廢水平均BOD為200mg/L，活性污泥曝氣槽有效容積為400m³，曝氣槽污泥濃度MLVSS=2，000mg/L，試問食微比為多少(kg BOD)/(kg MLVSS. day)?","options":["0.1","0.4","0.8","1.6"],"answer":2,"category":"活性污泥與操作控制"},{"id":368,"question":"試估算食微比","options":["0.32","0.42","0.52","0.62 kg BOD5/kg MLVSS. day"],"answer":2,"category":"活性污泥與操作控制"},{"id":369,"question":"試估算容積負荷F/V","options":["0.9","1.0","1.1","1.2 kg BOD/m³. day."],"answer":3,"category":"微生物與生物處理基礎"},{"id":370,"question":"試估算廢棄污泥量","options":["240","250","260","270 kg乾污泥/day"],"answer":1,"category":"微生物與生物處理基礎"},{"id":371,"question":"硝化菌群比生長速率慢，當廢水BOD/TKN之比值大於多少時，絕大部分的氮源將先被異營菌利用作為合成所需之碳源","options":["55","45","35","25"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":372,"question":"以下何者屬於會抑制硝化菌活性之物質","options":["濃度偏高的氨氮","重金屬","毒性有機化合物","以上皆是"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":373,"question":"處理污水量216，000m³/d的活性污泥曝氣池，其池中活性污泥混合液濃度MLSS=3，500mg/L，在曝氣池出水端取混合水樣1，000mL，靜置30min沉降後，活性污泥體積為360mL，請計算SVI值","options":["102.9","120.9","190.2","129.0."],"answer":1,"category":"活性污泥與操作控制"},{"id":374,"question":"活性污泥處理二沉池有細小污泥不斷外飄，以下可能之原因何者有誤","options":["污泥缺乏營養","進水中氨氮濃度高","進水pH值過低","池溫超過40度"],"answer":3,"category":"活性污泥與操作控制"},{"id":375,"question":"廢水生物處理系統受各類物質的毒性影響有分為3大類，其中某些有機物於高濃度時對微生物的生長產生抑制而低濃度時則無，如","options":["氨類","鹽分","銅類","酚類"],"answer":4,"category":"微生物與生物處理基礎"},{"id":376,"question":"殺菌劑、消毒劑及殺蟲劑，此等藥劑流入曝氣槽，會造成活性污泥解體，容許濃度為","options":["5","10","15","20 mg/L以下"],"answer":1,"category":"活性污泥與操作控制"},{"id":377,"question":"氧化渠之轉輪橫置於溝渠中，其作用為","options":["供給使溝渠內物質能完全混合所需之推力","輸入維持生物分解作用所需的氧","以上皆是","以上皆非"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":378,"question":"以下何種污泥處理方式適合處理:廢棄活性污泥、初級污泥混合廢棄活性污泥或滴濾池污泥","options":["厭氧消化","消化及脫硝","硝化及脫硝","好氧消化"],"answer":4,"category":"附著生長與生物膜"},{"id":379,"question":"以下活性污泥膜濾法MBR的特點，何者敘述有誤?","options":["適合中小型規模特殊污染物處理","初設成本較低，但操作成本高","污泥可以完全截留，系統操作維護容易","污泥停留時間可以相當長"],"answer":2,"category":"MBR 薄膜生物反應器"},{"id":380,"question":"厭氧性處理在缺氧情況下分解廢水有機物，透過酸形成菌產生","options":["有機酸","硫化物","氰化物","氨氮"],"answer":1,"category":"厭氧生物處理"},{"id":381,"question":"一廢水廠平均進流水量為1，600m³/day，進流入曝氣槽廢水平均BOD為200mg/L，活性污泥曝氣槽有效容積為400m³，曝氣槽污泥濃度MLVSS=2，000mg/L，試問容積負荷為多少(kg BOD5)/m³?","options":["0.8","1.0","1.1","1.2 kg BOD/m³. day."],"answer":1,"category":"活性污泥與操作控制"},{"id":382,"question":"以下對於厭氧消化過程中第二階段甲烷化之敘述何者有誤?","options":["酸生成作用產生短鏈脂肪酸，進一步轉化為甲烷、一氧化碳","甲烷生成菌又可分為嗜氫及嗜乙酸2類","適宜生長溫度包括中溫(35~37℃)及高溫(55℃)","此時廢水達到穩定，厭氧消化作用完成"],"answer":1,"category":"厭氧生物處理"},{"id":383,"question":"1 mg氨氮氧化為硝酸態氮，需耗用多少mg溶氧及8.64mg HCO3-","options":["2.3","3.3","4.3","5.3"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":384,"question":"表示每日供每公斤MLVSS攝食之有機污染物公斤量稱為","options":["F/V","F/M","SVI","MCRT"],"answer":2,"category":"活性污泥與操作控制"},{"id":385,"question":"以下何者是微生物的生長需求?","options":["能量來源、碳源","氮、硫、磷源、微量金屬","維生素、水","以上皆是"],"answer":4,"category":"微生物與生物處理基礎"},{"id":386,"question":"微生物依其對氧氣的需求可分為?","options":["好氧性處理","厭氧性處理","兼氧性處理","以上皆是"],"answer":4,"category":"微生物與生物處理基礎"},{"id":387,"question":"大腸桿菌屬於以下何種類的微生物?","options":["好氧性","厭氧性","兼氧性","缺氧性微生物"],"answer":3,"category":"微生物與生物處理基礎"},{"id":388,"question":"標準活性污泥法處理程序包括何種不同功能之設備","options":["將生物槽中之廢水和活性污泥混合液曝氣","藉二級沉澱池將活性污泥與處理水分開","迴流污泥之生物污泥使與進流原廢水混合","以上皆是"],"answer":4,"category":"活性污泥與操作控制"},{"id":389,"question":"曝氣槽有效容量中每一立方公尺容積每日所負荷之BOD5量稱為","options":["容積負荷","有機負荷","污泥齡","污泥容積指標"],"answer":1,"category":"活性污泥與操作控制"},{"id":390,"question":"影響生物硝化之因子為?","options":["溫度、pH值","溶氧、污泥齡","基質濃度、BOD/TKN比值","以上皆是"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":391,"question":"硝化反應必須在好氧的條件下進行，通常溶氧濃度多少mg/L為硝化反應的極限?","options":["0.5","1","3","5"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":392,"question":"一廢水廠平均進流水量為2，000m³/day，進流水平均BOD為300mg/L，處理水平均BOD為20mg/L，每公斤BOD去除產生0.40kg污泥，活性污泥曝氣槽有效容積為600m³，曝氣槽污泥濃度MLSS=2，500mg/L，MLVSS/MLSS=0.80，SV30=250. 估算F/M?","options":["0.5","1.0","1.5","2.0"],"answer":1,"category":"活性污泥與操作控制"},{"id":393,"question":"如上題估算:F/V?","options":["0.5","1.0","1.5","2.0 kg BOD/m³."],"answer":2,"category":"微生物與生物處理基礎"},{"id":394,"question":"如上題估算污泥齡?","options":["3.4","4.4","5.4","6.4 days."],"answer":3,"category":"活性污泥與操作控制"},{"id":395,"question":"如上題估算SVI?","options":["1","10","100","1，000 mL/g."],"answer":3,"category":"活性污泥與操作控制"},{"id":396,"question":"如上題估算XR?","options":["10","100","1，000","10，000 mg/L."],"answer":4,"category":"微生物與生物處理基礎"},{"id":397,"question":"A/O生物系統化學除磷(Phostrip程序)中，生物污泥在什麼情況下釋磷","options":["厭氧區","好氧區","生物污泥沉澱池","磷酸鈣沉澱池"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":398,"question":"批式活性污泥法為在同一槽內進行『A.靜置 B.沉降 C.排水 D.進流 E.反應』等之程序，下列哪一個順序正確?","options":["B、D、E、C、A","D、E、B、C、A","D、B、C、E、A","C、D、E、B、A"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":399,"question":"一般氧化深渠法之食微比(kg BOD5/kg MLVSS. day)，應維持在下列何者範圍?","options":["0.02~0.15","0.2~0.5","0.7~1.0","1.0~1.5"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":400,"question":"活性污泥曝氣槽有效容積為500m³、MLSS=2，000mg/L，MLVSS/MLSS=0.8，若進流水量為1，000m³/day，BOD為300mg/L，若30分鐘活性污泥的沉降體積(SV30)為250mL/L，則SVI為多少mL/g?","options":["125","100","80","150"],"answer":1,"category":"活性污泥與操作控制"},{"id":401,"question":"活性污泥增殖過程之對數增殖期，與減率增殖期及體內呼吸期相比較，下列敘述何者錯誤?","options":["對數增殖係在食微比較大時發生","對數增殖期內微生物去除有機物量較多","對數增殖期內之微生物之凝聚性及沉降性較佳","對數增殖期在減率增殖期之前發生"],"answer":3,"category":"活性污泥與操作控制"},{"id":402,"question":"下列何者為利用微生物將氨氮氧化轉化為亞硝酸鹽氮及硝酸鹽氮的反應?","options":["吸附反應","脫硝反應","硝化反應","水解反應"],"answer":3,"category":"脫氮除磷與營養鹽"},{"id":403,"question":"藉廢水與曝氣良好之活性污泥接觸，利用生物吸附作用，以去除大量BOD之處理程序為下列何者?","options":["接觸穩定法","階梯曝氣法","延長曝氣法","高率曝氣法"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":404,"question":"脫硝微生物利用廢水中有機物作為碳源，同時將硝酸根離子轉化成氮氣的處理是屬於下列何者?","options":["厭氧性處理","缺氧性處理","好氧性處理","兼氧性處理"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":405,"question":"有關微生物篩選槽(selector)應設置的位置，下列敘述何者正確?","options":["活性污泥生物反應槽之中段","活性污泥生物反應槽之前","活性污泥生物反應槽之後","與設置位置無關"],"answer":2,"category":"活性污泥與操作控制"},{"id":406,"question":"下列有關活性污泥自然培養法之敘述，何者有誤?","options":["自然培養法也稱直接培養法，又可分為間歇培養和連續培養兩種","自然培養法是利用廢水中原有的少量微生物，逐步繁殖的培養過程","容易生化處理的有機廢水，可以考慮自然培養法","自然培養法所需培養時間較直接培養法為短"],"answer":4,"category":"活性污泥與操作控制"},{"id":407,"question":"下列何者為脫硝反應的條件?","options":["pH控制在7.5~9.5","存在自營性菌","高溶氧濃度","需要有機碳源"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":408,"question":"接觸曝氣法接觸材料之種類，以下何者對水流之阻力較大，容易發生阻塞?","options":["平板體","波浪板體","網狀體","粒狀體"],"answer":4,"category":"附著生長與生物膜"},{"id":409,"question":"污泥厭氧消化操作參數中，消化污泥濃度(mg/L)約為下列何者?","options":["40~60","400~600","4，000~6，000","40，000~60，000"],"answer":3,"category":"污泥處理與處置"},{"id":410,"question":"一般生物除磷系統蓄積污泥中之磷含量(%)約為下列何者?","options":["2~3","5~10","11~15","16~20"],"answer":1,"category":"脫氮除磷與營養鹽"},{"id":411,"question":"下列有關磷蓄積菌之敘述，何者正確?","options":["磷蓄積菌在厭氧段時攝取正磷酸鹽","磷蓄積菌在好氧段時釋放正磷酸鹽","乙酸有利於磷蓄積菌於好氧段時蓄積能量儲存物","磷蓄積菌於好氧段時形成高含磷量的污泥"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":412,"question":"關於SBR與單槽連續進流SBR之基本特性差異，下列敘述何者錯誤?","options":["有機負荷均為週期變化","水力負荷均為週期變化","曝氣均為間歇式","排水均為週期排放"],"answer":1,"category":"SBR／氧化渠與改良活性污泥法"},{"id":413,"question":"下列何者為光合菌代謝最終產物","options":["O2","S","以上皆是","以上皆非"],"answer":3,"category":"微生物與生物處理基礎"},{"id":414,"question":"活性污泥曝氣槽有效容積為500m³、MLSS=2，000mg/L，MLVSS/MLSS=0.8，若進流水量為1，000m³/day，進流水BOD為300mg/L，試計算污泥齡約為多少day?","options":["5.3","5.7","6.6","7.2"],"answer":1,"category":"活性污泥與操作控制"},{"id":415,"question":"BOD為250mg/L，流量300m³/day之污水，以活性污泥法處理時，若有機負荷為0.3kg BOD/kg MLSS. day，MLVSS濃度為2，000mg/L，則曝氣槽有效容積(m³)為下列何者?","options":["125","200","250","300"],"answer":1,"category":"活性污泥與操作控制"},{"id":416,"question":"下列何者為具有生物除磷功能之處理程序?","options":["標準活性污泥法","厭氧/好氧標準活性污泥法","延長曝氣法","接觸曝氣法"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":417,"question":"厭氧系統鹼度不足時，添加有助於提高鹼度之化學藥品，不包括下列何者?","options":["NaHCO3","NaOH","Na2CO3","NaCl"],"answer":4,"category":"厭氧生物處理"},{"id":418,"question":"一般好氧生物處理之曝氣槽最好維持溶氧量在多少mg/L?","options":["0~1","1~3","3~5","5~7"],"answer":2,"category":"活性污泥與操作控制"},{"id":419,"question":"延長曝氣法係使曝氣槽中微生物進入下列哪一個增殖階段的方法?","options":["遲滯期","體內呼吸期","對數增殖期","減率增殖期"],"answer":2,"category":"SBR／氧化渠與改良活性污泥法"},{"id":420,"question":"一般微生物之脫硝反應係在於何種環境下進行?","options":["厭氧","兼氧","好氧","缺氧"],"answer":4,"category":"脫氮除磷與營養鹽"},{"id":421,"question":"下列何者非屬活性污泥法之曝氣池設計及操作參數?","options":["食微比","污泥齡","污泥容積指標","水面積負荷"],"answer":4,"category":"活性污泥與操作控制"},{"id":422,"question":"下列有關單槽連續進流批式活性污泥法之敘述，何者錯誤?","options":["最大的特色為進流是連續式，但反應與排水是間歇式","因為是連續進流，所以不需有進流與靜置處理階段","一般採正方形槽體，且在進流處裝置防止短流之隔板","處理槽係採低負荷的延長曝氣法"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":423,"question":"污泥厭氧消化系統採中溫操作時，下列敘述何者錯誤?","options":["最適合溫度範圍在30~38℃","應監測消化槽之曝氣量","應監測消化槽之揮發酸","應監測消化槽之鹼度"],"answer":2,"category":"厭氧生物處理"},{"id":424,"question":"污泥容積指標SVI的公式為","options":["SV30/MLSS","(Q*BOD)/(V*MLSS)","(Q*BOD)/V","以上皆非"],"answer":1,"category":"活性污泥與操作控制"},{"id":425,"question":"廢水生物處理系統受各類物質的毒性影響，會降低微生物的活性，降低生物處理效果，譬如於pH為7時，氯化物濃度一般不可大於多少mg/L?","options":["5，000","500","50","16"],"answer":1,"category":"微生物與生物處理基礎"},{"id":426,"question":"下列何者為一種在無氧狀態下反應，氧會與硝酸鹽與亞硝酸鹽競爭電子，迫使電子流轉向有氧呼吸作用，進而抑制氮氧化物還原為氮氣的反應稱為?","options":["吸附反應","脫硝反應","硝化反應","水解反應"],"answer":2,"category":"脫氮除磷與營養鹽"},{"id":427,"question":"以下氧化深渠基本的控制條件中，何者敘述有誤?","options":["低有機負荷","曝氣器供氧量之計算","表面溢流率","曝氣器輸氧量大小之控制"],"answer":3,"category":"SBR／氧化渠與改良活性污泥法"},{"id":428,"question":"活性污泥處理時發生二沉池上層液混濁，出水水質差，以下分析的原因中何者有誤?","options":["污泥負荷高","有機物氧化不完全","BOD上升","進水中洗滌劑含量過高"],"answer":4,"category":"活性污泥與操作控制"},{"id":429,"question":"以下活性污泥的敘述何者有誤?","options":["出現於活性污泥之纖毛蟲類共有67種","當有機負荷低時，微小鞭毛蟲會出現，且處理水之BOD5及SS較高","當BOD5負荷為0.2~0.3 kg BOD5/(kg MLVSS. day)時，原生動物的種類偏多","一般可從原生動物中的纖毛蟲大量出現，來判斷曝氣槽中活性污泥正處於成熟期"],"answer":2,"category":"活性污泥與操作控制"},{"id":430,"question":"廢水處理生物系統中，微生物生長及代謝作用最佳之pH值範圍為？","options":["2.0~4.0","4.5~6.0","6.5~7.5","8.5~10.0"],"answer":3,"category":"微生物與生物處理基礎"}];
